async function refreshSideStatus(){
  try {
    const result = await api('/api/health');
    const online = result.ok !== false;
    $('side-dot').className = `dot ${online ? 'online' : 'offline'}`;
    $('side-status').textContent = online ? '在线' : '离线';
  } catch (_) {
    $('side-dot').className = 'dot offline';
    $('side-status').textContent = '离线';
  }
}

refreshSideStatus();

function attachModelTestButtons(){
  if(current !== 'models') return;
  document.querySelectorAll('#config-rows tr').forEach((row, index) => {
    const actions = row.lastElementChild;
    if(!actions || row.querySelector('.empty-state') || actions.querySelector('[data-action="test"]')) return;
    const button = document.createElement('button');
    button.className = 'link-button';
    button.dataset.action = 'test';
    button.dataset.index = String(index);
    button.textContent = '测试';
    button.onclick = () => { button.textContent = '测试中...'; button.disabled = true; Promise.resolve(configAction('models', 'test', index)).finally(() => { button.textContent = '测试'; button.disabled = false; }); };
    actions.appendChild(button);
  });
}

const configPageObserver = new MutationObserver(attachModelTestButtons);
configPageObserver.observe($('dashboard'), {childList:true, subtree:true});
attachModelTestButtons();

function difficultyTag(value) {
  const names = {淼:'淼',水:'水',易:'易',普:'普',难:'难',虐:'虐'};
  const key = names[value] || '未分级';
  return `<span class="tag difficulty-${esc(key)}">${esc(key)}</span>`;
}

function libraryStatsCards(stats) {
  const difficulties = stats.difficulties || {};
  const difficultyText = ['淼','水','易','普','难','虐']
    .map(key => `<span class="stat-chip">${key} ${num(difficulties[key] || 0)}</span>`).join('');
  return `<div class="grid stats-grid library-stats">
    ${card('▥','文库总文章数',num(stats.texts))}
    <div class="card stat-card stat-wide"><div class="card-icon">◈</div><div><div class="card-label">难度分布</div><div class="stat-chips">${difficultyText}</div></div></div>
    ${card('✓','已分类 / 未分类',`${num(stats.classified_texts)} / ${num(stats.unclassified_texts)}`)}
    ${card('◉','进行中的发文会话',num(stats.active_sessions))}
  </div>`;
}

async function showLibraryText(item) {
  try {
    const result = await api(`/api/domain/library/text?text_id=${encodeURIComponent(item.text_id)}`);
    const text = result.data || {};
    openModal('文章详情', `<div class="article-meta"><strong>${esc(text.title || item.title)}</strong>${difficultyTag(text.difficulty || item.difficulty)} <span>${esc(text.genre || item.genre || '未分类')}</span> <span>${num(text.char_count || item.char_count)} 字</span></div><pre class="article-body">${esc(text.content || '正文暂不可用')}</pre>`, async () => {});
    const form = document.querySelector('#fm-form');
    if (form) form.querySelector('.modal-actions').innerHTML = '<button type="button" class="button secondary" data-close>关闭</button>';
    form?.querySelector('[data-close]')?.addEventListener('click', () => document.getElementById('fm-modal')?.remove());
  } catch (error) { toast(`文章加载失败：${error.message}`, 'error'); }
}

function renderLibraryResults(items) {
  return `<div class="card panel"><div class="table-wrap"><table><thead><tr><th>标题</th><th>难度</th><th>题材</th><th>文体</th><th>字数</th><th>操作</th></tr></thead><tbody>${items.map((item, index) => `<tr><td><button class="link-button" data-library-index="${index}">${esc(item.title || '未命名')}</button></td><td>${difficultyTag(item.difficulty)}</td><td>${esc(item.genre || '未分类')}</td><td>${esc(item.form || '未标注')}</td><td class="number">${num(item.char_count)}</td><td><button class="link-button" data-library-index="${index}">查看正文</button></td></tr>`).join('') || '<tr><td colspan="6"><div class="empty-state">未找到匹配的文章</div></td></tr>'}</tbody></table></div></div>`;
}

async function loadLibrary(query = {}) {
  loading(); setStatus('正在加载跟打文库...', 'loading');
  try {
    const qs = new URLSearchParams({limit:'20', ...query});
    const [statsResult, searchResult] = await Promise.all([
      api('/api/domain/library/stats'), api(`/api/domain/library/search?${qs}`)
    ]);
    const stats = statsResult.data || {}, items = Array.isArray(searchResult.data) ? searchResult.data : [];
    $('dashboard').innerHTML = `<div class="page-head"><div><h2>跟打文库</h2><p class="muted">${num(stats.characters)} 字 · ${num(stats.active_sessions || 0)} 个进行中会话</p></div><div class="filter-bar"><input id="library-q" placeholder="搜索标题或正文" value="${esc(query.q || '')}"><select id="library-difficulty"><option value="">全部难度</option>${['淼','水','易','普','难','虐'].map(x=>`<option ${query.difficulty===x?'selected':''}>${x}</option>`).join('')}</select><select id="library-genre"><option value="">全部题材</option>${Object.keys(stats.genres || {}).map(x=>`<option ${query.genre===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="button primary" id="library-search">搜索</button><button class="button secondary" id="library-reset">重置</button></div></div>${libraryStatsCards(stats)}${renderLibraryResults(items)}`;
    document.querySelectorAll('[data-library-index]').forEach(button => button.onclick = () => showLibraryText(items[Number(button.dataset.libraryIndex)]));
    $('library-search').onclick = () => loadLibrary({q:$('library-q').value, difficulty:$('library-difficulty').value, genre:$('library-genre').value});
    $('library-reset').onclick = () => loadLibrary();
    setStatus(`文库已加载，共 ${num(stats.texts)} 篇，当前显示 ${items.length} 篇`, 'success');
  } catch (error) { $('dashboard').innerHTML = `<div class="card notice"><h2>文库暂时无法加载</h2><p class="muted">数据服务暂时不可用：${esc(error.message)}</p><button class="button secondary" id="library-retry">重试</button></div>`; $('library-retry').onclick = () => loadLibrary(query); setStatus('文库加载失败', 'error'); }
}

function contestTable(items, mode) {
  if (mode === 'scores') return `<div class="card panel"><div class="table-wrap"><table><thead><tr><th>时间</th><th>用户</th><th>群</th><th>赛文 / 文章</th><th>速度</th><th>击键</th><th>字数</th><th>键准率</th></tr></thead><tbody>${items.map(x=>{const user=x.sender_name||x.user_name||x.name||x.sender_id||x.user_id||'';return `<tr><td>${esc(time(x.received_at || x.occurred_at || x.time))}</td><td><button class="link-button" data-score-user="${esc(user)}">${esc(user)}</button></td><td>${esc(x.group_name || x.source_group || x.group_id || '')}</td><td>${esc(x.title || x.text_title || (x.segment_id?`第${x.segment_id}段`:''))}</td><td class="number strong">${esc(x.speed ?? '')}</td><td class="number">${esc(x.keystroke ?? x.key ?? '')}</td><td class="number">${esc(x.characters ?? x.char_count ?? '')}</td><td class="number">${esc(x.accuracy ?? x.acc ?? '')}</td></tr>`}).join('') || '<tr><td colspan="8"><div class="empty-state">暂无成绩记录</div></td></tr>'}</tbody></table></div></div>`;
  return `<div class="card panel"><div class="table-wrap"><table><thead><tr><th>日期</th><th>标题</th><th>来源</th><th>字数</th><th>操作</th></tr></thead><tbody>${items.map((x,i)=>`<tr><td>${esc(x.competition_date || x.date || '')}</td><td><button class="link-button" data-contest-index="${i}">${esc(x.title || '未命名赛文')}</button></td><td>${esc(x.source_group || x.source || '未知')}</td><td class="number">${num(x.char_count || x.characters)}</td><td><button class="link-button" data-contest-index="${i}">查看正文</button></td></tr>`).join('') || '<tr><td colspan="5"><div class="empty-state">未找到匹配的赛文</div></td></tr>'}</tbody></table></div></div>`;
}

async function loadContestTab(tab = 'history') {
  loading(); setStatus('正在加载赛文成绩...', 'loading');
  try {
    let items = [], summary = {};
    if (tab === 'history') { const result = await api('/api/domain/contest/search?limit=20'); items = Array.isArray(result.data) ? result.data : []; }
    if (tab === 'scores') {
      let result;
      try { result = await api('/api/domain/scores?limit=20'); }
      catch (_) { result = await api('/api/domain/competition/scores?limit=20'); }
      items = Array.isArray(result.data) ? result.data : [];
    }
    if (tab === 'rank') { const result = await api('/api/domain/ai-contest/leaderboard'); items = result.data?.rows || []; summary = result.data || {}; }
    const body = tab === 'rank' ? `<div class="card panel"><div class="panel-head"><h2>AI 赛文排行榜</h2><span class="muted">${esc(summary.date || '当前赛事')}</span></div>${items.map((x,i)=>`<div class="rank-row rank-${i+1}"><strong>${i<3?['🥇','🥈','🥉'][i]:i+1}</strong><span>${esc(x.sender_name || x.user_name || x.name || x.user_id || '')}</span><b>${esc(x.speed ?? '')}</b></div>`).join('') || '<div class="empty-state">暂无排行榜数据</div>'}</div>` : contestTable(items, tab);
    $('dashboard').innerHTML = `<div class="page-head"><div><h2>赛文成绩</h2><p class="muted">历史赛文、跟打成绩与排行榜</p></div></div><div class="tabs"><button class="tab ${tab==='history'?'active':''}" data-contest-tab="history">历史赛文</button><button class="tab ${tab==='scores'?'active':''}" data-contest-tab="scores">成绩查询</button><button class="tab ${tab==='rank'?'active':''}" data-contest-tab="rank">排行榜</button></div>${tab==='history'?'<div class="filter-bar contest-filter"><input id="contest-q" placeholder="搜索赛文标题或正文"><button class="button primary" id="contest-search">搜索</button></div>':''}${body}`;
    document.querySelectorAll('[data-contest-tab]').forEach(button => button.onclick = () => loadContestTab(button.dataset.contestTab));
    document.querySelectorAll('[data-contest-index]').forEach(button => button.onclick = () => showContestText(items[Number(button.dataset.contestIndex)]));
    $('contest-search')?.addEventListener('click', () => loadContestTabWithQuery($('contest-q').value));
    setStatus(`赛文成绩已加载，共 ${items.length} 条`, 'success');
  } catch (error) { $('dashboard').innerHTML = `<div class="card notice"><h2>赛文成绩暂时无法加载</h2><p class="muted">数据服务暂时不可用：${esc(error.message)}</p><button class="button secondary" id="contest-retry">重试</button></div>`; $('contest-retry').onclick = () => loadContestTab(tab); setStatus('赛文成绩加载失败', 'error'); }
}

async function loadContestTabWithQuery(query) { const result = await api(`/api/domain/contest/search?limit=20&q=${encodeURIComponent(query)}`); const items = Array.isArray(result.data) ? result.data : []; const target = document.querySelector('.table-wrap tbody'); if (target) target.innerHTML = items.map((x,i)=>`<tr><td>${esc(x.competition_date || '')}</td><td><button class="link-button" data-contest-index="${i}">${esc(x.title || '')}</button></td><td>${esc(x.source_group || '')}</td><td class="number">${num(x.char_count)}</td><td>查看正文</td></tr>`).join('') || '<tr><td colspan="5"><div class="empty-state">未找到匹配的赛文</div></td></tr>'; }
async function showContestText(item) { try { const result = await api(`/api/domain/contest/pick?q=${encodeURIComponent(item.title || '')}&source=${encodeURIComponent(item.source_group || '')}&date=${encodeURIComponent(item.competition_date || '')}`); const text = result.data || {}; openModal('赛文正文', `<div class="article-meta"><strong>${esc(text.title || item.title)}</strong> <span>${num(text.char_count || item.char_count)} 字</span></div><pre class="article-body">${esc(text.content || '正文暂不可用')}</pre>`, async () => {}); const form = document.querySelector('#fm-form'); if(form) form.querySelector('.modal-actions').innerHTML='<button type="button" class="button secondary" data-close>关闭</button>'; form?.querySelector('[data-close]')?.addEventListener('click',()=>document.getElementById('fm-modal')?.remove()); } catch(error) { toast(`赛文加载失败：${error.message}`,'error'); } }

const showStage4Base = show;
show = function(view) { if(view === 'library') return loadLibrary(); if(view === 'contests') return loadContestTab(); return showStage4Base(view); };
if(location.hash === '#library') loadLibrary();
if(location.hash === '#contests') loadContestTab();

let stage5Timer = null;
function stage5Error(message, retry) { return `<div class="card notice"><strong>此区块暂时不可用</strong><p class="muted">${esc(message)}</p><button class="button secondary" data-stage5-retry>重试</button></div>`; }
function stage5Shell(title, id, content) { return `<section class="card panel stage5-block"><div class="panel-head"><h2>${title}</h2><button class="link-button" data-stage5-refresh="${id}">刷新</button></div><div id="stage5-${id}">${content}</div></section>`; }
function stage5Loading() { return '<div class="loading-box compact"><span class="skeleton"></span><span class="skeleton"></span></div>'; }
function runtimeStateTag(status) { const map={running:['运行中','running'],completed:['已完成','online'],failed:['失败','offline'],queued:['排队','queued'],cancelled:['已取消','offline']}; const item=map[status]||[status||'未知','queued']; return `<span class="tag ${item[1]}-tag">${item[0]}</span>`; }

async function loadRuntimeBlock(id, fn) {
  const target = $(`stage5-${id}`); if (!target) return;
  target.innerHTML = stage5Loading();
  try { target.innerHTML = await fn(); }
  catch (error) { target.innerHTML = stage5Error(`数据服务暂时不可用：${error.message}`, fn); target.querySelector('[data-stage5-retry]').onclick = () => loadRuntimeBlock(id, fn); }
}

async function renderRuntimeOverview() {
  const [health, observation] = await Promise.all([api('/api/health'), api('/api/observability/overview')]);
  const rpc = observation.rpc || {}, domain = observation.domain || {}, tasks = observation.tasks || {};
  return `<div class="grid status-grid">${service('◆','Cosmobot RPC',rpc)}${card('⚙','运行中任务',num(tasks.running || 0))}${service('◉','FM Domain',domain)}${card('↻','后台服务',health.ok ? '在线' : '离线')}</div><div class="card panel"><div class="metric-row"><span>RPC 延迟</span><strong>${esc(rpc.latency_ms ?? '未知')} ms</strong><span>任务总数</span><strong>${num((tasks.entries || []).length)}</strong></div></div>`;
}
async function renderRuntimeTasks() { const result=await api('/api/runtime/concurrency'); const entries=result.data?.entries || []; return entries.slice(0,20).map(x=>`<div class="task-row"><code>${esc(x.id)}</code><span>${esc(x.label || x.type || '任务')}</span>${runtimeStateTag(x.status)}<time>${esc(x.startedAt || '')}</time></div>`).join('') || '<div class="empty-state">暂无运行任务</div>'; }
async function renderRuntimeAudit() { const result=await api('/api/runtime/audit'); const items=Array.isArray(result.data)?result.data.slice(-50).reverse():[]; return `<div class="table-wrap"><table><thead><tr><th>时间</th><th>工具</th><th>调用者</th><th>参数摘要</th><th>状态</th></tr></thead><tbody>${items.map(x=>{const e=x.event||x; const call=e.toolCall||{}; return `<tr><td>${esc(e.occurredAt || '')}</td><td>${esc(call.name || e.toolName || '')}</td><td>${esc(e.runId || '')}</td><td><code>${esc((call.arguments || e.result || '').slice(0,100))}</code></td><td>${runtimeStateTag(e.status || e.tag?.includes('Finished')?'completed':'running')}</td></tr>`}).join('')||'<tr><td colspan="5"><div class="empty-state">暂无工具调用记录</div></td></tr>'}</tbody></table></div>`; }
async function renderRuntimeMedia() { const result=await api('/api/runtime/media'); const files=result.data?.files || []; const groups={image:0,audio:0,file:0,total:0}; files.forEach(x=>{const type=x.mimeType||''; const key=type.startsWith('image/')?'image':type.startsWith('audio/')?'audio':'file'; groups[key]++; groups.total+=Number(x.size||0)}); return `<div class="grid stats-grid">${card('▧','图片缓存',num(groups.image))}${card('♫','音频缓存',num(groups.audio))}${card('▤','文件缓存',num(groups.file))}${card('◈','总占用空间',`${(groups.total/1024/1024).toFixed(1)} MB`)}</div><div class="table-wrap"><table><thead><tr><th>文件</th><th>类型</th><th>大小</th><th>缓存时间</th></tr></thead><tbody>${files.slice(0,20).map(x=>`<tr><td><code>${esc(x.path || x.fileId || '')}</code></td><td>${esc(x.mimeType || '')}</td><td class="number">${num(x.size)} B</td><td>${esc(x.createdAtUnix ? time(x.createdAtUnix) : '')}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-state">暂无媒体缓存</div></td></tr>'}</tbody></table></div>`; }

function loadPipelinePage() {
  if (stage5Timer) { clearInterval(stage5Timer); stage5Timer=null; }
  $('dashboard').innerHTML = `<div class="page-head"><div><h2>消息链路</h2><p class="muted">运行时、任务、工具调用和媒体缓存</p></div></div><div class="stage5-grid">${stage5Shell('运行时状态概览','pipeline-overview',stage5Loading())}${stage5Shell('后台任务列表','pipeline-tasks',stage5Loading())}${stage5Shell('工具调用审计','pipeline-audit',stage5Loading())}${stage5Shell('媒体缓存状态','pipeline-media',stage5Loading())}</div>`;
  loadRuntimeBlock('pipeline-overview',renderRuntimeOverview); loadRuntimeBlock('pipeline-tasks',renderRuntimeTasks); loadRuntimeBlock('pipeline-audit',renderRuntimeAudit); loadRuntimeBlock('pipeline-media',renderRuntimeMedia);
  document.querySelectorAll('[data-stage5-refresh]').forEach(button=>button.onclick=()=>{const id=button.dataset.stage5Refresh; const fn={"pipeline-overview":renderRuntimeOverview,"pipeline-tasks":renderRuntimeTasks,"pipeline-audit":renderRuntimeAudit,"pipeline-media":renderRuntimeMedia}[id]; loadRuntimeBlock(id,fn);});
}

async function runtimeServiceBlock() { const [health,obs]=await Promise.all([api('/api/health'),api('/api/observability/overview')]); const service=(label,item,extra)=>`<div class="card service-card"><div class="service-title"><strong>${label}</strong><span class="dot ${item?.ok?'online':'offline'}"></span></div><b class="${item?.ok?'text-online':'text-offline'}">${item?.ok?'在线':'离线'}</b><p class="muted">${esc(extra)}</p></div>`; return `<div class="grid service-grid">${service('fm-admin',health,health.service||'后台服务')}${service('FM Domain',obs.domain,`端口 8077 · ${obs.domain?.reason||'健康检查正常'}`)}${service('Cosmobot',obs.rpc,`RPC 端口 · ${obs.rpc?.reason||'RPC 连接正常'}`)}</div>`; }
async function runtimeErrorsBlock() { const result=await api('/api/observability/overview'); const errors=result.recent_errors||[]; return `<div class="table-wrap"><table><thead><tr><th>时间</th><th>组件</th><th>错误信息</th></tr></thead><tbody>${errors.slice(-20).reverse().map(x=>`<tr><td>${esc(time(x.at))}</td><td>${esc(x.component||'系统')}</td><td title="${esc(x.error||'')}">${esc((x.error||'').slice(0,160))}</td></tr>`).join('')||'<tr><td colspan="3"><div class="empty-state">暂无最近错误</div></td></tr>'}</tbody></table></div>`; }
async function runtimeVersionsBlock() { const result=await api('/api/runtime/config/versions'); const items=result.items||[]; return `<div class="table-wrap"><table><thead><tr><th>版本号</th><th>时间</th><th>操作者</th><th>变更摘要</th></tr></thead><tbody>${items.slice(0,20).map(x=>`<tr><td><code>${esc(x.id||x.version_id||'')}</code></td><td>${esc(time(x.created_at||x.at))}</td><td>${esc(x.actor||x.operator||'admin')}</td><td>${esc(JSON.stringify(x.changes||x.summary||'').slice(0,160))}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-state">暂无配置变更历史</div></td></tr>'}</tbody></table></div>`; }
async function runtimeSystemBlock() { const now=new Date(); return `<div class="system-info"><span>服务器时间</span><strong>${esc(now.toLocaleString('zh-CN'))}</strong><span>后台 API</span><strong>正常响应</strong><span>自动刷新</span><strong>${stage5Timer?'已开启':'已关闭'}</strong></div>`; }
function loadRuntimePage() { if(stage5Timer){clearInterval(stage5Timer);stage5Timer=null;} $('dashboard').innerHTML=`<div class="page-head"><div><h2>运行状态</h2><p class="muted">服务健康、错误、配置历史和系统信息</p></div><label class="switch-label"><input id="runtime-auto" type="checkbox"> 自动刷新（30 秒）</label></div><div class="stage5-grid">${stage5Shell('服务状态总览','runtime-services',stage5Loading())}${stage5Shell('最近错误','runtime-errors',stage5Loading())}${stage5Shell('配置变更历史','runtime-versions',stage5Loading())}${stage5Shell('系统信息','runtime-system',stage5Loading())}</div>`; loadRuntimeBlock('runtime-services',runtimeServiceBlock);loadRuntimeBlock('runtime-errors',runtimeErrorsBlock);loadRuntimeBlock('runtime-versions',runtimeVersionsBlock);loadRuntimeBlock('runtime-system',runtimeSystemBlock);$('runtime-auto').onchange=event=>{if(event.target.checked){stage5Timer=setInterval(()=>{loadRuntimeBlock('runtime-services',runtimeServiceBlock);loadRuntimeBlock('runtime-errors',runtimeErrorsBlock);loadRuntimeBlock('runtime-versions',runtimeVersionsBlock);loadRuntimeBlock('runtime-system',runtimeSystemBlock)},30000)}else{clearInterval(stage5Timer);stage5Timer=null}}; }

const showStage5Base = show;
show = function(view) { if(view==='messages') return loadPipelinePage(); if(view==='runtime') return loadRuntimePage(); return showStage5Base(view); };
if(location.hash === '#messages') loadPipelinePage();
if(location.hash === '#runtime') loadRuntimePage();

let chatStage6 = {items:[], shown:50, groups:[]};
function chatFilter6(item, state) {
  if(state.group && String(item.group_id) !== state.group) return false;
  if(state.keyword && !`${item.text||''} ${item.sender_name||''} ${item.sender_id||''}`.toLowerCase().includes(state.keyword.toLowerCase())) return false;
  if(state.days){ const ts=Number(item.occurred_at||0); if(ts < Date.now()/1000 - state.days*86400) return false; }
  return true;
}
function renderChat6() {
  const state={group:$('chat-group')?.value||'',keyword:$('chat-keyword-6')?.value||'',days:Number($('chat-days')?.value||0)};
  const items=chatStage6.items.filter(x=>chatFilter6(x,state));
  const visible=items.slice(0,chatStage6.shown);
  const rows=visible.map((m,i)=>`<article class="message-item" data-chat-index="${chatStage6.items.indexOf(m)}"><div><strong>${esc(m.sender_name||m.sender_id||'-')}</strong><span class="muted"> · ${esc(m.group_name||m.group_id||'私聊')} · ${esc(time(m.occurred_at))}</span></div><p>${esc(m.text||'（非文本消息）')}</p><small class="muted">${esc(m.message_id||'-')}</small></article>`).join('')||'<div class="empty-state">暂无匹配消息</div>';
  const list=$('chat-list-6'); if(list) list.innerHTML=rows;
  const more=$('chat-more-6'); if(more){more.disabled=visible.length>=items.length;more.textContent=visible.length<items.length?`加载更多（还剩 ${items.length-visible.length} 条）`:'已加载全部匹配消息';}
  document.querySelectorAll('[data-chat-index]').forEach(x=>x.onclick=()=>{const m=chatStage6.items[Number(x.dataset.chatIndex)];openModal('消息详情',`<pre class="article-body">${esc(JSON.stringify(m,null,2))}</pre>`,async()=>{});const f=$('#fm-form');if(f)f.querySelector('.modal-actions').innerHTML='<button type="button" class="button secondary" data-close>关闭</button>';f?.querySelector('[data-close]')?.addEventListener('click',()=>$('#fm-modal')?.remove());});
}
async function loadChatStage6(){loading();setStatus('正在加载聊天记录...','loading');try{const [g,r]=await Promise.all([api('/api/domain/groups'),api('/api/domain/recent-messages?limit=100')]);chatStage6.groups=Array.isArray(g.data)?g.data:[];chatStage6.items=Array.isArray(r.data)?r.data:[];chatStage6.shown=50;$('dashboard').innerHTML=`<div class="page-head"><div><h2>聊天记录</h2><p class="muted">支持按群、时间、内容和发送者筛选</p></div></div><div class="filter-bar"><select id="chat-group"><option value="">全部群</option>${chatStage6.groups.map(x=>`<option value="${esc(x.group_id)}">${esc(x.display_name||x.group_id)}</option>`).join('')}</select><select id="chat-days"><option value="0">全部时间</option><option value="1">今天</option><option value="7">近 7 天</option><option value="30">近 30 天</option></select><input id="chat-keyword-6" placeholder="搜索内容、发送者昵称或 QQ"><button class="button primary" id="chat-search-6">筛选</button></div><div class="card panel"><div id="chat-list-6" class="message-list"></div><button class="button secondary load-more" id="chat-more-6">加载更多</button></div>`;renderChat6();$('chat-search-6').onclick=()=>{chatStage6.shown=50;renderChat6()};$('chat-more-6').onclick=()=>{chatStage6.shown+=50;renderChat6()};setStatus(`聊天记录已加载，共 ${chatStage6.items.length} 条`,'success')}catch(e){$('dashboard').innerHTML=`<div class="card notice"><h2>聊天记录暂时无法加载</h2><p class="muted">数据服务暂时不可用：${esc(e.message)}</p><button class="button secondary" id="chat-retry-6">重试</button></div>`;$('chat-retry-6').onclick=loadChatStage6;setStatus('聊天记录加载失败','error')}}

let logsStage6={items:[],page:1};
function renderLogs6(){const actor=$('log-actor-6')?.value.toLowerCase()||'',action=$('log-action-6')?.value.toLowerCase()||'',resource=$('log-resource-6')?.value.toLowerCase()||'',keyword=$('log-keyword-6')?.value.toLowerCase()||'',source=$('log-source-6')?.value||'';const items=logsStage6.items.filter(x=>(!actor||String(x.actor||'').toLowerCase().includes(actor))&&(!action||String(x.action||'').toLowerCase().includes(action))&&(!resource||String(x.collection||'').toLowerCase().includes(resource))&&(!keyword||JSON.stringify(x).toLowerCase().includes(keyword))&&(!source||(source==='admin'&&x.source!=='runtime')||(source==='runtime'&&x.source==='runtime')));const total=Math.max(1,Math.ceil(items.length/20));logsStage6.page=Math.min(logsStage6.page,total);const pageItems=items.slice((logsStage6.page-1)*20,logsStage6.page*20);const body=pageItems.map((x,i)=>{const key=`log6-${(logsStage6.page-1)*20+i}`;return `<tr><td>${esc(time(x.at))}</td><td>${x.source==='runtime'?'<span class="tag running-tag">Cosmobot</span>':'<span class="tag">后台</span>'}</td><td>${esc(x.actor||'-')}</td><td>${esc(x.action||'-')}</td><td>${esc(`${x.collection||'-'} / ${x.item_id||'-'}`)}</td><td><button class="link-button" data-log6="${key}">查看</button></td></tr><tr id="${key}" class="hidden"><td colspan="6"><pre>${esc(JSON.stringify(x,null,2))}</pre></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty-state">暂无日志记录</div></td></tr>';$('logs-body-6').innerHTML=body;document.querySelectorAll('[data-log6]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.log6).classList.toggle('hidden'));$('logs-page-6').textContent=`第 ${logsStage6.page} 页 / 共 ${total} 页`;$('logs-prev-6').disabled=logsStage6.page<=1;$('logs-next-6').disabled=logsStage6.page>=total;}
async function loadLogsStage6(){loading();setStatus('正在加载审计日志...','loading');try{const r=await api('/api/logs?limit=200');logsStage6.items=r.items||[];$('dashboard').innerHTML=`<div class="page-head"><div><h2>审计日志</h2><p class="muted">支持来源、操作者、动作、资源、关键词和时间筛选</p></div></div><div class="filter-bar"><select id="log-source-6"><option value="">全部来源</option><option value="admin">后台</option><option value="runtime">Cosmobot</option></select><input id="log-actor-6" placeholder="操作者"><input id="log-action-6" placeholder="动作"><input id="log-resource-6" placeholder="资源类型"><input id="log-keyword-6" placeholder="关键词"><button class="button primary" id="logs-filter-6">筛选</button></div><div class="card panel"><div class="table-wrap"><table><thead><tr><th>时间</th><th>来源</th><th>操作者</th><th>动作</th><th>资源 / ID</th><th>详情</th></tr></thead><tbody id="logs-body-6"></tbody></table></div><div class="pagination"><button class="button secondary" id="logs-prev-6">上一页</button><span id="logs-page-6"></span><button class="button secondary" id="logs-next-6">下一页</button></div></div>`;renderLogs6();$('logs-filter-6').onclick=()=>{logsStage6.page=1;renderLogs6()};$('logs-prev-6').onclick=()=>{logsStage6.page--;renderLogs6()};$('logs-next-6').onclick=()=>{logsStage6.page++;renderLogs6()};setStatus(`审计日志已加载，共 ${logsStage6.items.length} 条`,'success')}catch(e){setStatus(`审计日志加载失败：${e.message}`,'error')}}

async function loadGroupsStage6(){loading();setStatus('正在加载群与房间...','loading');try{const [r,p]=await Promise.all([api('/api/domain/groups'),api('/api/collections/personas')]);const groups=Array.isArray(r.data)?r.data:[],personas=p.items||[];const caps=['agent','library','contest','ai_contest','scores','recall','repeat','score_archive'];const labels={agent:'AI 对话',library:'跟打',contest:'赛文',ai_contest:'AI 赛文',scores:'成绩',recall:'撤回',repeat:'自动跟随',score_archive:'成绩归档'};const rows=groups.map((g,i)=>{let f={};try{f=JSON.parse(g.features_json||'{}')}catch(_){};const tags=caps.filter(x=>f[x]).map(x=>`<span class="tag">${labels[x]}</span>`).join('')||'<span class="muted">无已启用能力</span>';return `<tr><td><code>${esc(g.group_id)}</code></td><td>${esc(g.display_name||'未命名群')}</td><td>${g.paused?'<span class="tag paused-tag">暂停</span>':'<span class="tag online-tag">上线</span>'}</td><td>${tags}</td><td>默认</td><td><button class="link-button" data-group6-edit="${i}">编辑设置</button></td></tr>`}).join('');$('dashboard').innerHTML=`<div class="page-head"><div><h2>群与房间</h2><p class="muted">实时群状态与群能力配置</p></div><button class="button primary" id="groups-refresh-6">同步群列表</button></div><div class="card panel"><div class="table-wrap"><table><thead><tr><th>群号</th><th>群名称</th><th>状态</th><th>群能力</th><th>群级人设</th><th>操作</th></tr></thead><tbody>${rows||'<tr><td colspan="6"><div class="empty-state">暂无群数据</div></td></tr>'}</tbody></table></div></div>`;document.querySelectorAll('[data-group6-edit]').forEach(b=>b.onclick=()=>groupSettingsStage6(groups[Number(b.dataset.group6Edit)],personas,caps,labels));$('groups-refresh-6').onclick=loadGroupsStage6;setStatus(`群列表已更新，共 ${groups.length} 个群`,'success')}catch(e){setStatus(`群列表加载失败：${e.message}`,'error')}}
async function groupSettingsStage6(g,personas,caps,labels){let state={};try{state=(await api(`/api/domain/group-capability?group_id=${encodeURIComponent(g.group_id)}`)).data||{}}catch(_){}const abilities=state.capabilities||{};const body=`<p><strong>${esc(g.display_name||g.group_id)}</strong></p>${select('运行状态','online',[['true','上线'],['false','暂停']],g.paused?'false':'true')}<div class="field"><span>群能力</span>${caps.map(c=>`<label class="checkbox"><input type="checkbox" name="cap_${c}" ${abilities[c]?'checked':''}> ${labels[c]}</label>`).join('')}</div>${select('群级人设','persona',[['','使用默认'],...personas.map(p=>[p.id,p.name||p.id])],'')}`;openModal('群设置',body,async values=>{await api('/api/domain/group-state',{method:'POST',body:JSON.stringify({group_id:g.group_id,online:values.online==='true'})});for(const c of caps)await api('/api/domain/group-capability',{method:'POST',body:JSON.stringify({group_id:g.group_id,capability:c,enabled:values[`cap_${c}`]==='on'})});toast('群设置已保存');await loadGroupsStage6()});}

const showStage6Base=show; show=function(view){if(view==='chat')return loadChatStage6();if(view==='logs')return loadLogsStage6();if(view==='groups')return loadGroupsStage6();return showStage6Base(view)}; if(location.hash==='#chat')loadChatStage6();if(location.hash==='#logs')loadLogsStage6();if(location.hash==='#groups')loadGroupsStage6();


async function loadGroups(){loading();setStatus("正在加载群与房间...","loading");try{const r=await api("/api/domain/groups"),groups=Array.isArray(r.data)?r.data:[];$('dashboard').innerHTML=`<div class="page-head"><div><h2>群与房间</h2><p class="muted">来自 FM Domain 的实时群列表</p></div><button class="button primary" id="sync-groups">↻ 同步群列表</button></div><div class="card panel"><div class="table-wrap"><table><thead><tr><th>群号</th><th>群名称</th><th>状态</th><th>群能力</th><th>最后更新</th><th>操作</th></tr></thead><tbody>${groups.map((g,i)=>`<tr><td><code>${esc(g.group_id)}</code></td><td>${esc(g.display_name||"未命名群")}</td><td>${g.paused?'<span class="tag paused-tag">暂停</span>':'<span class="tag online-tag">上线</span>'}</td><td><span class="tag">默认能力</span></td><td>${esc(time(g.updated_at))}</td><td><button class="link-button" data-group-edit="${i}">编辑设置</button><button class="link-button" data-group-toggle="${i}">${g.paused?'上线':'暂停'}</button></td></tr>`).join("")||'<tr><td colspan="6"><div class="empty-state">暂无群数据</div></td></tr>'}</tbody></table></div></div>`;$("sync-groups").onclick=loadGroups;document.querySelectorAll('[data-group-edit]').forEach(b=>b.onclick=()=>groupSettings(groups[Number(b.dataset.groupEdit)]));document.querySelectorAll('[data-group-toggle]').forEach(b=>b.onclick=async()=>{const g=groups[Number(b.dataset.groupToggle)];try{await api('/api/domain/group-state',{method:'POST',body:JSON.stringify({group_id:g.group_id,online:!!g.paused})});toast(g.paused?'群已上线':'群已暂停');loadGroups()}catch(e){toast(e.message,'error')}});setStatus(`群列表已更新，共 ${groups.length} 个群`,'success')}catch(e){setStatus(`加载失败：${e.message}`,'error')}}
function groupSettings(g) {
  const body = [
    `<p><strong>${esc(g.display_name || g.group_id)}</strong></p>`,
    select('运行状态', 'online', [['true', '上线'], ['false', '暂停']], g.paused ? 'false' : 'true'),
    select('自动跟随', 'repeat_follow', [['true', '启用'], ['false', '停用']], 'true')
  ].join('');
  openModal('群设置', body, async values => {
    await api('/api/domain/group-state', {
      method: 'POST',
      body: JSON.stringify({ group_id: g.group_id, online: values.online === 'true' })
    });
    await api('/api/domain/repeat-follow', {
      method: 'POST',
      body: JSON.stringify({ group_id: g.group_id, enabled: values.repeat_follow === 'true' })
    });
    toast('群设置已保存');
    await loadGroups();
  });
}
async function loadChat(){loading();setStatus("正在加载最近消息...","loading");try{const r=await api('/api/domain/recent-messages?limit=50'),items=Array.isArray(r.data)?r.data:[];$('dashboard').innerHTML=`<div class="page-head"><div><h2>聊天记录</h2><p class="muted">最近消息，默认显示 50 条</p></div><div class="filter-bar"><input id="chat-keyword" placeholder="搜索关键词"><button class="button primary" id="chat-search">搜索</button></div></div><div class="card panel"><div class="message-list">${items.map(m=>`<article class="message-item"><div><strong>${esc(m.sender_name||m.sender_id||'未知用户')}</strong><span class="muted"> · ${esc(m.group_name||m.group_id||'私聊')} · ${esc(time(m.occurred_at))}</span></div><p>${esc(m.text||'')}</p></article>`).join("")||'<div class="empty-state">未找到匹配的消息</div>'}</div></div>`;$("chat-search").onclick=async()=>{const x=await api('/api/domain/recent-messages?limit=50&keyword='+encodeURIComponent($("chat-keyword").value));const list=Array.isArray(x.data)?x.data:[];document.querySelector('.message-list').innerHTML=list.map(m=>`<article class="message-item"><strong>${esc(m.sender_name||m.sender_id||'未知用户')}</strong><span class="muted"> · ${esc(time(m.occurred_at))}</span><p>${esc(m.text||'')}</p></article>`).join("")||'<div class="empty-state">未找到匹配的消息</div>'};setStatus(`消息记录已加载，共 ${items.length} 条`,'success')}catch(e){setStatus(`加载失败：${e.message}`,'error')}}
async function loadLogsPage(){loading();setStatus("正在加载审计日志...","loading");try{const r=await api('/api/logs?limit=100'),items=r.items||[];$('dashboard').innerHTML=`<div class="page-head"><div><h2>审计日志</h2><p class="muted">后台操作与 Cosmobot 运行事件</p></div><div class="filter-bar"><input id="log-keyword" placeholder="关键词"><button class="button primary" id="log-search">筛选</button></div></div><div class="card panel"><div class="table-wrap"><table><thead><tr><th>时间</th><th>来源</th><th>操作者</th><th>动作</th><th>资源 / ID</th><th>详情</th></tr></thead><tbody>${items.map((x,i)=>`<tr><td>${esc(time(x.at))}</td><td><span class="tag">${x.source==='runtime'?'Cosmobot':'后台'}</span></td><td>${esc(x.actor||'admin')}</td><td><span class="tag">${esc(x.action||'')}</span></td><td>${esc((x.collection||'')+' / '+(x.item_id||''))}</td><td><button class="link-button" data-log-index="${i}">查看</button></td></tr><tr id="log-detail-${i}" class="hidden"><td colspan="6"><pre>${esc(JSON.stringify(x.detail||x,null,2))}</pre></td></tr>`).join("")||'<tr><td colspan="6"><div class="empty-state">暂无日志记录</div></td></tr>'}</tbody></table></div></div>`;document.querySelectorAll('[data-log-index]').forEach(b=>b.onclick=()=>$("log-detail-"+b.dataset.logIndex).classList.toggle('hidden'));setStatus(`审计日志已加载，共 ${items.length} 条`,'success')}catch(e){setStatus(`加载失败：${e.message}`,'error')}}
