const renderLogsStage6Base=renderLogs6;
renderLogs6=function(){const all=logsStage6.items,days=Number($('log-days-6')?.value||0),cutoff=days?Date.now()/1000-days*86400:0;logsStage6.items=cutoff?all.filter(x=>Number(x.at||x.created_at||0)>=cutoff):all;renderLogsStage6Base();logsStage6.items=all};
const loadLogsStage6Base=loadLogsStage6;
loadLogsStage6=async function(){await loadLogsStage6Base();if(!$('log-days-6')){const select=document.createElement('select');select.id='log-days-6';select.innerHTML='<option value="0">全部时间</option><option value="1">今天</option><option value="7">近 7 天</option>';$('logs-filter-6').before(select)}};
const renderConfigStage6Base=renderConfig;
