async function groupSettingsStage6WithPersona(g,personas,caps,labels){let state={};try{state=(await api(`/api/domain/group-capability?group_id=${encodeURIComponent(g.group_id)}`)).data||{}}catch(_){}const abilities=state.capabilities||{};let snap={};try{snap=data(await api('/api/runtime/config'))}catch(_){}const bound=(snap.group_personas||[]).find(p=>String(p.group_id||p.scope||'')===String(g.group_id));const body=`<p><strong>${esc(g.display_name||g.group_id)}</strong></p>${select('运行状态','online',[['true','上线'],['false','暂停']],g.paused?'false':'true')}<div class="field"><span>群能力</span>${caps.map(c=>`<label class="checkbox"><input type="checkbox" name="cap_${c}" ${abilities[c]?'checked':''}> ${labels[c]}</label>`).join('')}</div>${select('群级人设','persona',[['','使用默认'],...personas.map(p=>[p.id,p.name||p.id])],bound?.id||'')}`;openModal('群设置',body,async values=>{await api('/api/domain/group-state',{method:'POST',body:JSON.stringify({group_id:g.group_id,online:values.online==='true'})});for(const c of caps)await api('/api/domain/group-capability',{method:'POST',body:JSON.stringify({group_id:g.group_id,capability:c,enabled:values[`cap_${c}`]==='on'})});const selected=personas.find(p=>String(p.id)===String(values.persona));if(selected)await api('/api/runtime/config/persona',{method:'POST',body:JSON.stringify({action:'set',scope:'group',id:g.group_id,content:selected.content||selected.prompt||selected.text||''})});toast('群设置已保存');await loadGroupsStage6()})}
groupSettingsStage6=groupSettingsStage6WithPersona;

function runtimeValue(value, fallback='-') { return value === undefined || value === null || value === '' ? fallback : value; }
function runtimeTime(value) { return value === undefined || value === null || value === '' ? '-' : time(value); }
function runtimeStatus(value) { const s=String(value||'').toLowerCase(); if(s.includes('fail')||s.includes('error')) return 'failed'; if(s.includes('cancel')) return 'cancelled'; if(s.includes('queue')||s.includes('pending')) return 'queued'; if(s.includes('complete')||s.includes('finish')||s.includes('success')) return 'completed'; return 'running'; }
const renderRuntimeAuditStage6=renderRuntimeAudit;
renderRuntimeAudit=async function(){const result=await api('/api/runtime/audit'),raw=Array.isArray(result.data)?result.data:[],items=raw.slice(-50).reverse().map(x=>{const e=x.event||x,call=e.toolCall||e.tool_call||{};return {e,call,at:x.occurredAt||e.occurredAt||e.occurred_at||e.at||e.time||e.started_at||e.timestamp,args:call.arguments||e.arguments||e.result||'',name:call.name||e.toolName||e.tool_name}}).filter(x=>x.name||x.call.arguments||x.e.arguments);return `<div class="audit-filter"><label><input type="checkbox" checked disabled> 只显示工具调用</label><span class="muted">已过滤无工具名的内部任务记录</span></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>工具</th><th>调用者</th><th>参数摘要</th><th>状态</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(runtimeTime(x.at))}</td><td>${esc(runtimeValue(x.name))}</td><td>${esc(runtimeValue(x.e.runId||x.e.run_id||x.e.agentId||x.e.agent_id))}</td><td><code>${esc(String(x.args).slice(0,100)||'-')}</code></td><td>${runtimeStateTag(runtimeStatus(x.e.status||x.e.state||x.e.tag))}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">暂无工具调用记录</div></td></tr>'}</tbody></table></div>`};
const renderRuntimeTasksStage6=renderRuntimeTasks;
renderRuntimeTasks=async function(){const result=await api('/api/runtime/concurrency'),entries=result.data?.entries||[];return entries.slice(0,20).map(x=>`<div class="task-row"><code>${esc(runtimeValue(x.id))}</code><span>${esc(runtimeValue(x.label||x.type))}</span>${runtimeStateTag(runtimeStatus(x.status))}<time>${esc(runtimeValue(x.startedAt||x.started_at||x.createdAt||x.created_at))}</time></div>`).join('')||'<div class="empty-state">暂无运行任务</div>';};
const renderRuntimeMediaStage6=renderRuntimeMedia;
renderRuntimeMedia=async function(){const result=await api('/api/runtime/media'),files=result.data?.files||[];const groups={image:0,audio:0,file:0,total:0};files.forEach(x=>{const type=String(x.mimeType||x.mime_type||'');const key=type.startsWith('image/')?'image':type.startsWith('audio/')?'audio':'file';groups[key]++;groups.total+=Number(x.size||0)});return `<div class="grid stats-grid">${card('▧','图片缓存',num(groups.image))}${card('♫','音频缓存',num(groups.audio))}${card('▤','文件缓存',num(groups.file))}${card('◈','总占用空间',`${(groups.total/1024/1024).toFixed(1)} MB`)}</div><div class="table-wrap"><table><thead><tr><th>文件</th><th>类型</th><th>大小</th><th>缓存时间</th></tr></thead><tbody>${files.slice(0,20).map(x=>`<tr><td><code>${esc(runtimeValue(x.path||x.fileId||x.file_id))}</code></td><td>${esc(runtimeValue(x.mimeType||x.mime_type))}</td><td class="number">${num(x.size)} B</td><td>${esc(runtimeValue(x.createdAtUnix?time(x.createdAtUnix):x.created_at||x.createdAt))}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-state">暂无媒体缓存</div></td></tr>'}</tbody></table></div>`;};
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('fm-modal')?.remove()});

let contestStage6={tab:'history',items:[],page:1};
