function personaRuntimeForm(scope,item={},groups=[]){const isGroup=scope==='group',isPrivate=scope==='private',isDefault=scope.endsWith('_default'),label=isGroup?'群号':isPrivate?'QQ号':'用户QQ号';const options=isGroup?`<select name="id" required><option value="">选择群</option>${groups.map(g=>`<option value="${esc(g.group_id)}" ${String(item.id)===String(g.group_id)?'selected':''}>${esc(g.display_name||g.group_id)}</option>`).join('')}</select>`:isDefault?'':field(label,'id',item.id||'', 'text',true);return `${isGroup?`<label class="field"><span>群号</span>${options}</label>`:options}${area('Prompt 内容','content',item.content||'',true)}`}
