async function loadChatArchiveStage8(query={}){loading();setStatus('正在读取永久消息归档...','loading');try{const groups=await api('/api/domain/groups');const list=Array.isArray(groups.data)?groups.data:[];chatArchiveStage8={items:[],before:0,query,loading:false};$('dashboard').innerHTML=`<div class="page-head"><div><h2>聊天记录</h2><p class="muted">永久消息归档，可按游标加载更早历史</p></div></div><div class="filter-bar"><select id="chat-archive-group"><option value="">全部群</option>${list.map(g=>`<option value="${esc(g.group_id)}">${esc(g.display_name||g.group_id)}</option>`).join('')}</select><input id="chat-archive-q" placeholder="搜索内容、发送者昵称或 QQ"><button class="button primary" id="chat-archive-search">筛选</button></div><div class="card panel"><div id="chat-range-archive" class="muted"></div><div id="chat-list-archive" class="message-list"></div><button class="button secondary load-more" id="chat-more-archive">加载更早消息</button></div>`;const fetchPage=async(reset)=>{const group=$('chat-archive-group').value,q=$('chat-archive-q').value;const params=new URLSearchParams({limit:'50'});if(group)params.set('group_id',group);if(q)params.set('q',q);if(!reset&&chatArchiveStage8.before)params.set('before',String(chatArchiveStage8.before));const result=await api(`/api/domain/recent-messages?${params}`),received=Array.isArray(result.data)?result.data:[];chatArchiveStage8.items=reset?received:chatArchiveStage8.items.concat(received);chatArchiveStage8.before=received.length?Number(received[received.length-1].occurred_at):chatArchiveStage8.before;renderChatArchiveStage8()};$('chat-archive-search').onclick=()=>{chatArchiveStage8.before=0;chatArchiveStage8.items=[];fetchPage(true)};$('chat-more-archive').onclick=()=>fetchPage(false);await fetchPage(true);setStatus(`永久消息归档已加载，共 ${chatArchiveStage8.items.length} 条`,'success')}catch(e){$('dashboard').innerHTML=`<div class="card notice"><h2>消息归档暂时无法加载</h2><p class="muted">${esc(e.message)}</p></div>`;setStatus(`加载失败：${e.message}`,'error')}}
