function openTokenCreate(){const modal=openModal('生成新 Token',field('Token 名称','name','','text',true)+field('过期时间（可选）','expires_at','','datetime-local',false),async values=>{const payload={name:values.name};if(values.expires_at)payload.expires_at=Date.parse(values.expires_at)/1000;const result=await api('/api/auth/tokens',{method:'POST',body:JSON.stringify(payload)});modal.remove();const created=openModal('Token 已生成',`<p>完整 Token 只显示这一次，请立即复制保存。</p><pre>${esc(result.token)}</pre>`,async()=>{});created.querySelector('.modal-actions').innerHTML='<button type="button" class="button primary" data-close>关闭</button>';created.querySelector('[data-close]').onclick=()=>created.remove();tokenManagementPage()});return modal}
