/* Stage 13 dashboard: independent panels keep the cockpit usable during partial outages. */
function dashboardPanel(title, id, content='<div class="dashboard-skeleton"><span></span><span></span><span></span></div>') {
  return `<div class="card panel dashboard-panel" id="${id}"><div class="panel-head"><h2>${title}</h2></div><div class="dashboard-panel-body">${content}</div></div>`;
}
function dashboardFailure(id, message, retry) {
  const el=$(id); if(!el)return;
  el.innerHTML=`<div class="dashboard-error"><strong>该区块加载失败</strong><p>${esc(message)}</p><button class="button secondary" data-dashboard-retry>重试</button></div>`;
  el.querySelector('[data-dashboard-retry]')?.addEventListener('click',retry);
}
function dashboardMetric(icon,label,value,change) {
  const pct=Number(change); const trend=Number.isFinite(pct)?`${pct>=0?'↑':'↓'} ${Math.abs(pct).toFixed(1)}%`:'-';
  return `<div class="card dashboard-metric"><div class="dashboard-metric-icon">${icon}</div><div><div class="card-label">${label}</div><div class="dashboard-metric-value">${esc(num(value))}</div><div class="dashboard-trend ${pct>=0?'up':'down'}">${trend} 较昨日</div></div></div>`;
}
function dashboardChange(today, yesterday) { const a=Number(today)||0,b=Number(yesterday)||0; return b?((a-b)/b*100):null; }
function ensureEcharts(){const lib=window.echarts||globalThis.echarts;return lib?Promise.resolve(lib):Promise.reject(new Error("图表库加载失败，请刷新页面"))}
function renderDashboardCharts(daily) {
  const trend=$('dashboard-message-chart'),groups=$('dashboard-group-chart');
  if(!trend||!groups)return;
  ensureEcharts().then(chartLib=>{
    if(!chartLib){trend.innerHTML='<div class="dashboard-error">图表库加载失败，请重试。</div>';groups.innerHTML='<div class="dashboard-error">图表库加载失败，请重试。</div>';return;}
    const days=Array.isArray(daily.days)?daily.days:[], labels=days.map(x=>x.date), values=days.map(x=>Number(x.count)||0);
    const trendChart=chartLib.init(trend); trendChart.setOption({animationDuration:450,grid:{left:46,right:18,top:20,bottom:32},tooltip:{trigger:'axis'},xAxis:{type:'category',data:labels},yAxis:{type:'value',minInterval:1},series:[{type:'line',smooth:true,data:values,symbolSize:7,lineStyle:{color:'#2563eb',width:3},itemStyle:{color:'#2563eb'},areaStyle:{color:'rgba(37,99,235,.10)'}}]});
    const gs=(Array.isArray(daily.groups)?daily.groups:[]).slice().reverse(), names=gs.map(x=>x.group_name||x.group_id||'-'), counts=gs.map(x=>Number(x.count)||0);
    const groupChart=chartLib.init(groups); groupChart.setOption({animationDuration:450,grid:{left:100,right:24,top:12,bottom:24},tooltip:{trigger:'axis'},xAxis:{type:'value',minInterval:1},yAxis:{type:'category',data:names,axisLabel:{width:90,overflow:'truncate'}},series:[{type:'bar',data:counts,barMaxWidth:18,itemStyle:{color:'#38a169',borderRadius:[0,4,4,0]}}]});
    const resize=()=>{trendChart.resize();groupChart.resize();}; window.addEventListener('resize',resize,{passive:true});
  });
}
function dashboardMessages(items) {
  return (Array.isArray(items)?items:[]).slice(0,15).map(m=>`<article class="dashboard-message" data-message-id="${esc(m.message_id||'')}"><div><strong>${esc(m.group_name||m.group_id||'私聊')}</strong><span class="muted"> · ${esc(m.sender_name||m.sender_id||'-')} · ${esc(time(m.occurred_at))}</span></div><p>${esc(m.text||'（非文本消息）')}</p></article>`).join('')||'<div class="empty-state">暂无消息</div>';
}
function readable(value,fallback='-') {
  if(value===undefined||value===null||value==='')return fallback;
  if(typeof value==='string'||typeof value==='number'||typeof value==='boolean')return String(value);
  if(Array.isArray(value))return value.map(x=>readable(x,'')).filter(Boolean).join(', ')||fallback;
  if(typeof value==='object') {
    for(const key of ['name','title','label','value','id','type','action','event','resource','collection','message']) {
      if(value[key]!==undefined&&value[key]!==null&&value[key]!=='')return readable(value[key],fallback);
    }
    try{return JSON.stringify(value)}catch(_){return fallback}
  }
  return fallback;
}
function auditEventParts(item) {
  const x=item?.event&&typeof item.event==='object'?{...item,...item.event}:item||{};
  const tool=x.toolCall||x.tool_call||{};
  return {at:x.at||x.time||x.created_at||x.occurredAt||x.occurred_at||x.started_at||x.timestamp,who:readable(x.actor||x.user||x.operator||x.runId||x.run_id||x.agentId||x.agent_id,'系统'),action:readable(x.action||x.event_name||x.kind||tool.name||x.event,'操作'),resource:readable(x.collection||x.resource||x.item_id||x.target||tool.name,'-')};
}
function dashboardEvents(audit,errors) {
  const events=[];
  (Array.isArray(audit)?audit:[]).slice(0,12).forEach(x=>events.push(auditEventParts(x)));
  (Array.isArray(errors)?errors:[]).slice(0,8).forEach(x=>events.push({at:x.at||x.time||x.created_at,who:readable(x.component,'系统'),action:'错误',resource:readable(x.error||x.message||x.detail,'-')}));
  return events.sort((a,b)=>(Number(b.at)||0)-(Number(a.at)||0)).slice(0,20).map(x=>`<li><span class="timeline-dot"></span><div><time>${esc(runtimeTime(x.at))}</time><strong>${esc(readable(x.who,'系统'))}</strong><span>${esc(readable(x.action,'操作'))} · ${esc(readable(x.resource,'-'))}</span></div></li>`).join('')||'<li class="empty-state">暂无最近事件</li>';
}
function dashboardAlerts(snapshot,errors) {
  const recent=(Array.isArray(errors)?errors:[]).filter(x=>Number(x.at||x.time||0)>=Date.now()/1000-3600), alerts=[];
  if(snapshot?.domain?.ok===false)alerts.push('FM Domain 当前离线');
  if(snapshot?.rpc?.ok===false)alerts.push('Cosmobot RPC 当前离线');
  if(recent.length>10)alerts.push(`最近 1 小时错误 ${recent.length} 条，超过阈值`);
  return alerts.length?`<div class="dashboard-alerts">${alerts.map(x=>`<div class="dashboard-alert">⚠ ${esc(x)}</div>`).join('')}</div>`:'';
}
