const dashboardStableState={messageIds:new Set(),eventSignature:'',timer:null,request:0};
function stableMetric(icon,label,value,change,key){const pct=Number(change);const trend=Number.isFinite(pct)?`${pct>=0?'↑':'↓'} ${Math.abs(pct).toFixed(1)}%`:'-';return `<div class="card dashboard-metric" data-dashboard-metric="${key}"><div class="dashboard-metric-icon">${icon}</div><div><div class="card-label">${label}</div><div class="dashboard-metric-value">${esc(num(value))}</div><div class="dashboard-trend ${pct>=0?'up':'down'}">${trend} 较昨日</div></div></div>`}
function stableDashboardShell(){return `<div class="dashboard-stage13"><div id="dashboard-metrics" class="dashboard-metrics">${[1,2,3,4].map(()=>'<div class="card dashboard-metric dashboard-loading"></div>').join('')}</div><div class="dashboard-chart-grid">${dashboardPanel('近 7 天消息量趋势','dashboard-trend-panel','<div id="dashboard-message-chart" class="dashboard-chart"></div>')}${dashboardPanel('群活跃度排行 · Top 10','dashboard-group-panel','<div id="dashboard-group-chart" class="dashboard-chart"></div>')}</div><div class="dashboard-feed-grid">${dashboardPanel('实时消息流','dashboard-messages')}${dashboardPanel('最近事件','dashboard-events','<ul class="dashboard-timeline"><li class="dashboard-skeleton"><span></span><span></span></li></ul>')}</div><div id="dashboard-alerts"></div></div>`}
 function updateStableChart(id,option,attempt=0){const el=document.getElementById(id),lib=window.echarts||globalThis.echarts;if(!el||!lib){if(attempt<3)setTimeout(()=>updateStableChart(id,option,attempt+1),100);return}try{const existing=lib.getInstanceByDom?.(el);if(existing)existing.dispose();el.innerHTML='';const chart=lib.init(el);chart.setOption(option,{notMerge:true});chart.resize()}catch(error){if(attempt<3)setTimeout(()=>updateStableChart(id,option,attempt+1),100);else console.warn('[chart] failed:',id,error)}}
function updateStableCharts(daily){const days=Array.isArray(daily.days)?daily.days:[],groups=(Array.isArray(daily.groups)?daily.groups:[]).slice().reverse();updateStableChart('dashboard-message-chart',{animation:false,grid:{left:46,right:18,top:20,bottom:32},tooltip:{trigger:'axis'},xAxis:{type:'category',data:days.map(x=>x.date)},yAxis:{type:'value',minInterval:1},series:[{type:'line',smooth:true,data:days.map(x=>Number(x.count)||0),symbolSize:6,lineStyle:{color:'#2563eb',width:3},itemStyle:{color:'#2563eb'}}]});updateStableChart('dashboard-group-chart',{animation:false,grid:{left:100,right:24,top:12,bottom:24},tooltip:{trigger:'axis'},xAxis:{type:'value',minInterval:1},yAxis:{type:'category',data:groups.map(x=>x.group_name||x.group_id||'-'),axisLabel:{width:90,overflow:'truncate'}},series:[{type:'bar',data:groups.map(x=>Number(x.count)||0),barMaxWidth:18,itemStyle:{color:'#38a169',borderRadius:[0,4,4,0]}}]})}
function updateStableMessages(items){const host=$('dashboard-messages')?.querySelector('.dashboard-panel-body');if(!host)return;const list=Array.isArray(items)?items.slice(0,15):[];const fresh=list.filter(m=>{const id=String(m.message_id||`${m.occurred_at}-${m.sender_id}-${m.text}`);if(dashboardStableState.messageIds.has(id))return false;dashboardStableState.messageIds.add(id);return true});fresh.reverse().forEach(m=>{const article=document.createElement('article');article.className='dashboard-message';article.dataset.messageId=m.message_id||'';article.innerHTML=`<div><strong>${esc(m.group_name||m.group_id||'私聊')}</strong><span class="muted"> · ${esc(m.sender_name||m.sender_id||'-')} · ${esc(time(m.occurred_at))}</span></div><p>${esc(m.text||'（非文本消息）')}</p>`;article.onclick=()=>{location.hash='chat';show('chat')};host.insertBefore(article,host.firstChild)});while(host.children.length>15)host.lastElementChild.remove();if(!fresh.length&&!host.children.length)host.innerHTML='<div class="empty-state">暂无消息</div>'}
function updateStableEvents(audit,errors){const html=dashboardEvents(Array.isArray(audit)?audit:[],Array.isArray(errors)?errors:[]),host=$('dashboard-events')?.querySelector('.dashboard-panel-body');if(!host)return;if(html!==dashboardStableState.eventSignature){host.innerHTML=`<ul class="dashboard-timeline">${html}</ul>`;dashboardStableState.eventSignature=html}}
