function ensureStage2Panels(){const root=document.querySelector('.dashboard-stage13');if(!root||$('dashboard-heatmap-chart'))return;const grid=document.createElement('div');grid.className='dashboard-chart-grid dashboard-stage2-charts';grid.innerHTML=`${dashboardPanel('24 小时消息热力图','dashboard-heatmap-panel','<div id="dashboard-heatmap-chart" class="dashboard-chart"></div>')}${dashboardPanel('模型调用统计','dashboard-model-panel','<div class="model-stats-grid"><div id="dashboard-model-chart" class="dashboard-chart model-pie-chart"></div><div id="dashboard-model-latency" class="dashboard-chart model-latency-chart"></div></div>')}${dashboardPanel('成绩速度分布','dashboard-speed-panel','<div id="dashboard-speed-chart" class="dashboard-chart"></div>')}`;root.querySelector('.dashboard-feed-grid')?.before(grid)}
function renderStage2Charts(advanced){if(!(window.echarts||globalThis.echarts))return;const dark=document.body.classList.contains('dark-mode'),axis=dark?'#9aa9c2':'#718096',split=dark?'#2a3855':'#eef1f5',text=dark?'#e0e0e0':'#172033';const heat=Array.isArray(advanced?.heatmap)?advanced.heatmap:[],speed=Array.isArray(advanced?.speed_distribution)?advanced.speed_distribution:[];updateStableChart('dashboard-heatmap-chart',{animation:false,textStyle:{color:text},grid:{left:48,right:18,top:22,bottom:34},tooltip:{position:'top'},xAxis:{type:'category',data:Array.from({length:24},(_,i)=>`${i}时`),axisLabel:{color:axis}},yAxis:{type:'category',data:['周一','周二','周三','周四','周五','周六','周日'],axisLabel:{color:axis}},visualMap:{min:0,max:Math.max(1,...heat.map(x=>Number(x.count)||0)),calculable:false,orient:'horizontal',left:'center',bottom:0,inRange:{color:dark?['#172554','#2563eb','#67e8f9']:['#eff6ff','#60a5fa','#1d4ed8']}},series:[{type:'heatmap',data:heat.map(x=>[Number(x.hour),Number(x.day),Number(x.count)||0])}]});const audits=Array.isArray(advanced?.audit)?advanced.audit:[],modelMap={};audits.forEach(item=>{const x=item?.event&&typeof item.event==='object'?{...item,...item.event}:item||{},m=readable(x.model||x.model_name||x.provider||x.toolCall?.model,'未标注');if(!modelMap[m])modelMap[m]={count:0,total:0};modelMap[m].count++;modelMap[m].total+=Number(x.elapsed_ms||x.duration_ms||x.latency_ms||0)||0});const modelNames=Object.keys(modelMap),modelCounts=modelNames.map(x=>modelMap[x].count),modelAvg=modelNames.map(x=>modelMap[x].count?Math.round(modelMap[x].total/modelMap[x].count):0);updateStableChart('dashboard-model-chart',{animation:false,textStyle:{color:text},tooltip:{trigger:'item'},legend:{orient:'vertical',left:'left',textStyle:{color:text}},series:[{type:'pie',radius:['42%','72%'],center:['58%','50%'],data:modelNames.length?modelNames.map((name,i)=>({name,value:modelCounts[i]})):[{name:'暂无数据',value:1}],label:{color:text}}]});updateStableChart('dashboard-model-latency',{animation:false,textStyle:{color:text},tooltip:{trigger:'axis'},grid:{left:44,right:18,top:20,bottom:38},xAxis:{type:'category',data:modelNames.length?modelNames:['暂无数据'],axisLabel:{color:axis,rotate:modelNames.length>3?25:0}},yAxis:{type:'value',name:'ms',axisLabel:{color:axis},splitLine:{lineStyle:{color:split}}},series:[{type:'bar',data:modelNames.length?modelAvg:[0],barMaxWidth:30,itemStyle:{color:'#f59e0b'}}]});updateStableChart('dashboard-speed-chart',{animation:false,textStyle:{color:text},tooltip:{trigger:'axis'},grid:{left:44,right:18,top:20,bottom:38},xAxis:{type:'category',data:speed.length?speed.map(x=>x.range):['暂无数据'],axisLabel:{color:axis}},yAxis:{type:'value',minInterval:1,axisLabel:{color:axis},splitLine:{lineStyle:{color:split}}},series:[{type:'bar',data:speed.length?speed.map(x=>Number(x.count)||0):[0],barMaxWidth:30,itemStyle:{color:'#38a169'}}]})}
function ensureHealthCard(){const root=document.querySelector('.dashboard-stage13');if(!root||$('dashboard-health-card'))return;const card=document.createElement('div');card.id='dashboard-health-card';card.className='card health-score-card';card.innerHTML='<div class="health-score-ring"><span id="health-score-value">-</span></div><div><h2>机器人健康评分</h2><p id="health-score-summary" class="muted">正在计算服务健康度...</p><div id="health-score-issues" class="health-issues"></div></div>';root.insertBefore(card,root.firstChild)}
async function refreshHealthCard(){const result=await api('/api/health/score').catch(()=>null),card=$('dashboard-health-card');if(!card||!result?.ok)return;const score=Math.max(0,Math.min(100,Number(result.score)||0)),ring=card.querySelector('.health-score-ring');ring.style.setProperty('--score',`${score*3.6}deg`);ring.classList.toggle('health-good',score>=80);ring.classList.toggle('health-warn',score>=60&&score<80);ring.classList.toggle('health-bad',score<60);$('health-score-value').textContent=score;$('health-score-summary').textContent=score>=80?'服务运行良好':score>=60?'服务需要关注':'服务存在风险';$('health-score-issues').innerHTML=(result.issues||[]).slice(0,3).map(x=>`<div>${esc(readable(x.issue||x.message,'-'))} <span>${esc(readable(x.suggestion,'-'))}</span></div>`).join('')||'<div class="muted">暂无待处理问题</div>'}
const loadStableDashboardStage2Base=loadStableDashboard;loadStableDashboard=async function(){await loadStableDashboardStage2Base();if(current!=='overview')return;ensureHealthCard();refreshHealthCard();ensureStage2Panels();const result=await api('/api/dashboard/advanced').catch(()=>null);if(result?.ok){const domain=result.domain?.data||{},audit=result.audit?.data;renderStage2Charts({...domain,audit:Array.isArray(audit)?audit:(audit?.entries||audit?.items||[])})}};

function openGroupDetailStage2(groupId){const modal=openModal('群详情','<div class="loading-box"><span class="spinner"></span><span>正在加载群详情...</span></div>',async()=>{});modal.querySelector('.modal-actions').innerHTML='<button type="button" class="button secondary" data-close>关闭</button>';modal.querySelector('[data-close]').onclick=()=>modal.remove();api(`/api/domain/group/${encodeURIComponent(groupId)}/detail`).then(result=>{const d=result.data||{},daily=Array.isArray(d.daily)?d.daily:[],users=Array.isArray(d.active_users)?d.active_users:[],events=Array.isArray(d.events)?d.events:[];modal.querySelector('.form-body').innerHTML=`<div class="group-detail-summary"><strong>${esc(readable(d.display_name||d.group_id))}</strong><span>${esc(d.group_id||'-')}</span><span class="tag ${d.paused?'paused-tag':'online-tag'}">${d.paused?'暂停':'上线'}</span></div><div class="group-detail-chart" id="group-detail-chart"></div><h3 class="detail-subtitle">活跃用户 TOP10</h3><div class="group-detail-users">${users.map(x=>`<div><span>${esc(x.sender_name||x.sender_id||'-')}</span><b>${num(x.count)}</b></div>`).join('')||'<div class="empty-state">暂无活跃用户数据</div>'}</div><h3 class="detail-subtitle">近期事件</h3><ul class="dashboard-timeline">${events.map(x=>`<li><span class="timeline-dot"></span><div><time>${esc(runtimeTime(x.occurred_at))}</time><span>${esc(x.sender_name||'-')} · ${esc(x.text||'-')}</span></div></li>`).join('')||'<li class="empty-state">暂无近期事件</li>'}</ul>`;if(window.echarts){const c=window.echarts.init($('group-detail-chart'));c.setOption({animation:false,grid:{left:40,right:15,top:15,bottom:30},xAxis:{type:'category',data:daily.map(x=>x.date)},yAxis:{type:'value',minInterval:1},series:[{type:'line',data:daily.map(x=>Number(x.count)||0),smooth:true,lineStyle:{color:'#2563eb'}}]})}}).catch(error=>{modal.querySelector('.form-body').innerHTML=`<div class="dashboard-error">群详情加载失败：${esc(error.message)}</div>`})}
const loadGroupsStage2Base=loadGroupsStage6;loadGroupsStage6=async function(){await loadGroupsStage2Base();document.querySelectorAll('[data-group6-edit]').forEach(button=>{if(button.parentElement.querySelector('[data-group-detail]'))return;const row=button.closest('tr'),groupId=row?.querySelector('code')?.textContent.trim();if(groupId){const detail=document.createElement('button');detail.className='link-button';detail.dataset.groupDetail=groupId;detail.textContent='详情';detail.onclick=()=>openGroupDetailStage2(groupId);button.parentElement.appendChild(detail)}})};

/* Stage 14 visual controls and compact live telemetry. */
function applyTheme(dark){document.body.classList.toggle('dark-mode',dark);const button=$('theme-toggle');if(button){button.textContent=dark?'☀':'☾';button.title=dark?'切换亮色模式':'切换暗黑模式';button.setAttribute('aria-label',button.title)}try{localStorage.setItem('fm-theme',dark?'dark':'light')}catch(_){}const axis=dark?'#9aa9c2':'#718096',split=dark?'#2a3855':'#eef1f5',text=dark?'#e0e0e0':'#172033';document.querySelectorAll('.dashboard-chart,.group-detail-chart').forEach(el=>{const chart=(window.echarts||globalThis.echarts)?.getInstanceByDom?.(el);chart?.setOption({textStyle:{color:text},xAxis:{axisLine:{lineStyle:{color:axis}},axisLabel:{color:axis},splitLine:{lineStyle:{color:split}}},yAxis:{axisLine:{lineStyle:{color:axis}},axisLabel:{color:axis},splitLine:{lineStyle:{color:split}}}},{lazyUpdate:true})})}
function initStage14Header(){const actions=document.querySelector('.top-actions');if(!actions||$('theme-toggle'))return;const dark=(()=>{try{return localStorage.getItem('fm-theme')==='dark'}catch(_){return false}})();const theme=document.createElement('button');theme.id='theme-toggle';theme.className='button secondary theme-toggle';theme.onclick=()=>applyTheme(!document.body.classList.contains('dark-mode'));actions.insertBefore(theme,actions.firstChild);const status=document.createElement('div');status.id='top-live-status';status.className='top-live-status';status.innerHTML='<span class="live-metric">消息 <b id="live-rate">-</b>/分</span><span class="live-metric">模型 <b id="live-model">-</b></span><span class="live-services" title="后台 / Domain / Cosmobot"><i id="live-admin" class="live-service-dot"></i><i id="live-domain" class="live-service-dot"></i><i id="live-rpc" class="live-service-dot"></i></span>';actions.insertBefore(status,theme);applyTheme(dark)}
function setLiveDot(id,ok,label){const el=$(id);if(el){el.className=`live-service-dot ${ok?'online':'offline'}`;el.title=`${label}：${ok?'在线':'离线'}`}}
async function refreshStage14Telemetry(){if(!$('top-live-status'))return;const now=Date.now()/1000;const [messages,config,overview]=await Promise.allSettled([api('/api/domain/recent-messages?limit=100'),api('/api/runtime/config'),api('/api/observability/overview')]);if(messages.status==='fulfilled'){const items=data(messages.value),rate=(Array.isArray(items)?items:[]).filter(x=>Number(x.occurred_at||0)>=now-60).length,el=$('live-rate');if(el&&el.textContent!==String(rate)){el.textContent=String(rate);el.classList.remove('live-rate-bump');void el.offsetWidth;el.classList.add('live-rate-bump')}}if(config.status==='fulfilled'){const snap=data(config.value),model=(snap.models||[]).find(x=>x.current);if($('live-model'))$('live-model').textContent=readable(model?.model||model?.provider,'-')}if(overview.status==='fulfilled'){const x=overview.value;setLiveDot('live-admin',true,'后台');setLiveDot('live-domain',x.domain?.ok!==false,'Domain');setLiveDot('live-rpc',x.rpc?.ok!==false,'Cosmobot')}}
initStage14Header();refreshStage14Telemetry();setInterval(refreshStage14Telemetry,10000);
/* Stage 14.2 final automatic dashboard renderer */
var dashboardAutoRun=0;
function dashboardPayload(result){return result&&result.data&&typeof result.data==='object'?result.data:result||{}}
function renderHealthScoreStage2(result){try{const h=dashboardPayload(result),score=Math.max(0,Math.min(100,Number(h.score)||0)),card=$('health-score-card');if(!card)return;const ring=card.querySelector('.health-score-ring');if(ring){ring.id='health-score-gauge';ring.innerHTML='';updateStableChart('health-score-gauge',{animation:false,series:[{type:'gauge',startAngle:210,endAngle:-30,min:0,max:100,progress:{show:true,width:10,itemStyle:{color:score>=80?'#38a169':score>=60?'#d69e2e':'#e53e3e'}},axisLine:{lineStyle:{width:10,color:[[1,'#e8edf5']]}},pointer:{show:false},axisTick:{show:false},splitLine:{show:false},axisLabel:{show:false},detail:{valueAnimation:false,fontSize:22,fontWeight:'bold',color:score>=80?'#276749':score>=60?'#975a16':'#c53030',offsetCenter:[0,'8%'],formatter:'{value}'},data:[{value:score}]}]})}const summary=$('health-score-summary');if(summary)summary.textContent=(score>=80?'服务运行良好':score>=60?'服务需要关注':'服务存在风险')+' · '+score+'分';const issues=$('health-score-issues');if(issues)issues.innerHTML=(h.issues||[]).slice(0,3).map(x=>'<div>'+esc(readable(x.issue||x.message,'-'))+' <span>'+esc(readable(x.suggestion,'-'))+'</span></div>').join('')||'<div class="muted">暂无待处理问题</div>'}catch(error){console.error('[dashboard] health render failed',error)}}

/* Stage 3: keyboard commands, notifications, and progressive table enhancements. */
const stage3State={notifications:[],commandIndex:0,tableObserver:null};
function stage3IsAdmin(){return /管理员/.test(document.querySelector('.account-user')?.textContent||'')}
function stage3Notify(title,content,type='info'){const item={id:Date.now()+Math.random(),title,content,type,at:Date.now(),read:false};stage3State.notifications.unshift(item);stage3State.notifications=stage3State.notifications.slice(0,50);try{localStorage.setItem('fm-notifications',JSON.stringify(stage3State.notifications))}catch(_){}renderStage3Notifications();}
function renderStage3Notifications(){const panel=$('stage3-notification-panel'),badge=$('stage3-notification-badge');if(!panel)return;const unread=stage3State.notifications.filter(x=>!x.read).length;if(badge){badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('hidden',!unread)}panel.querySelector('.stage3-notification-list').innerHTML=stage3State.notifications.map(x=>`<button class="stage3-notification ${x.read?'read':''}" data-notification-id="${x.id}"><b>${esc(x.title)}</b><span>${esc(x.content)}</span><small>${esc(time(x.at/1000))}</small></button>`).join('')||'<div class="empty-state">暂无通知</div>'}
function toggleStage3Notifications(){const p=$('stage3-notification-panel');if(p)p.classList.toggle('hidden')}
function openStage3CommandPanel(){let old=$('stage3-command-modal');if(old){old.remove();return}const admin=stage3IsAdmin(),commands=[['打开仪表盘',()=>show('overview'),false],['打开聊天记录',()=>show('chat'),false],['打开群与房间',()=>show('groups'),false],['打开成绩中心',()=>show('contests'),false],['刷新当前页面',()=>show(current),false],['切换暗黑模式',()=>applyTheme(!document.body.classList.contains('dark-mode')),false],['导出当前表格',()=>stage3ExportTable(),false],['切换模型',()=>show('models'),true],['重启服务',()=>toast('重启服务需在服务器侧执行','info'),true],['生成 Token',()=>show('access'),true]] .filter(x=>!x[2]||admin);const m=document.createElement('div');m.id='stage3-command-modal';m.className='modal-backdrop';m.innerHTML=`<div class="modal command-modal"><div class="modal-head"><h2>命令面板</h2><button class="icon-button" data-stage3-close>×</button></div><div class="command-search"><input id="stage3-command-input" placeholder="输入命令名称..." autocomplete="off"></div><div id="stage3-command-list" class="command-list"></div></div>`;document.body.appendChild(m);const input=$('stage3-command-input'),list=$('stage3-command-list');const render=()=>{const q=input.value.trim().toLowerCase(),items=commands.filter(x=>x[0].toLowerCase().includes(q));stage3State.commandIndex=Math.min(stage3State.commandIndex,Math.max(0,items.length-1));list.innerHTML=items.map((x,i)=>`<button class="command-item ${i===stage3State.commandIndex?'active':''}" data-command-index="${i}">${esc(x[0])}</button>`).join('')||'<div class="empty-state">未找到命令</div>';list.querySelectorAll('[data-command-index]').forEach(b=>b.onclick=()=>{items[Number(b.dataset.commandIndex)][1]();m.remove()})};input.oninput=render;input.onkeydown=e=>{const items=commands.filter(x=>x[0].toLowerCase().includes(input.value.trim().toLowerCase()));if(e.key==='ArrowDown'){e.preventDefault();stage3State.commandIndex=(stage3State.commandIndex+1)%Math.max(1,items.length);render()}else if(e.key==='ArrowUp'){e.preventDefault();stage3State.commandIndex=(stage3State.commandIndex-1+items.length)%Math.max(1,items.length);render()}else if(e.key==='Enter'&&items[stage3State.commandIndex]){items[stage3State.commandIndex][1]();m.remove()}};m.querySelector('[data-stage3-close]').onclick=()=>m.remove();m.onclick=e=>{if(e.target===m)m.remove()};render();input.focus()}
function stage3ExportTable(){const table=document.querySelector('#dashboard table');if(!table){toast('当前页面没有可导出的表格','info');return}const rows=[...table.rows].map(r=>[...r.cells].map(c=>c.innerText.replace(/\n/g,' ')));const blob=new Blob([rows.map(r=>r.map(x=>`"${x.replace(/"/g,'""')}"`).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fm-export.csv';a.click();URL.revokeObjectURL(a.href);toast('表格已导出')}
 function enhanceStage3Table(table){if(table.dataset.stage3Enhanced)return;table.dataset.stage3Enhanced='1';table.classList.add('stage3-table');const head=table.tHead?.rows[0];if(!head)return;[...head.cells].forEach((cell,index)=>{cell.classList.add('sortable');cell.title='点击排序';cell.onclick=()=>{const body=table.tBodies[0];if(!body)return;const asc=cell.dataset.sort!=='asc';cell.dataset.sort=asc?'asc':'desc';[...head.cells].forEach(x=>{if(x!==cell)delete x.dataset.sort});[...body.rows].sort((a,b)=>{const av=a.cells[index]?.innerText||'',bv=b.cells[index]?.innerText||'';return (Number(av)-Number(bv)||av.localeCompare(bv,'zh-CN'))*(asc?1:-1)}).forEach(r=>body.appendChild(r));};});[...(table.tBodies[0]?.rows||[])].forEach(row=>{row.classList.add('stage3-expandable');row.onclick=e=>{if(e.target.closest('button,input,select,a'))return;let detail=row.nextElementSibling;if(detail?.classList.contains('stage3-row-detail')){detail.remove();return}detail=document.createElement('tr');detail.className='stage3-row-detail';detail.innerHTML=`<td colspan="${row.cells.length}"><pre>${esc([...row.cells].map(c=>c.innerText).join(' | '))}</pre></td>`;row.after(detail);};});}
function initStage3Tables(){document.querySelectorAll('#dashboard table').forEach(enhanceStage3Table);if(!stage3State.tableObserver){stage3State.tableObserver=new MutationObserver(()=>document.querySelectorAll('#dashboard table').forEach(enhanceStage3Table));stage3State.tableObserver.observe($('dashboard'),{childList:true,subtree:true})}}
function initStage3(){try{stage3State.notifications=JSON.parse(localStorage.getItem('fm-notifications')||'[]').slice(0,50)}catch(_){}const top=document.querySelector('.top-actions');if(top&&!$('stage3-notification-button')){const b=document.createElement('button');b.id='stage3-notification-button';b.className='button secondary stage3-icon-button';b.title='通知中心';b.textContent='♢';b.onclick=toggleStage3Notifications;const badge=document.createElement('span');badge.id='stage3-notification-badge';badge.className='stage3-badge hidden';b.appendChild(badge);const p=document.createElement('div');p.id='stage3-notification-panel';p.className='stage3-notification-panel hidden';p.innerHTML='<div class="stage3-notification-head"><strong>通知中心</strong><button class="link-button" id="stage3-read-all">全部已读</button></div><div class="stage3-notification-list"></div>';top.appendChild(b);document.body.appendChild(p);$('stage3-read-all').onclick=()=>{stage3State.notifications.forEach(x=>x.read=true);stage3Notify('通知中心','已全部标记为已读','info');stage3State.notifications.shift();renderStage3Notifications()};renderStage3Notifications()}initStage3Tables();document.addEventListener('keydown',e=>{const input=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(e.key==='Escape'){document.querySelectorAll('.modal-backdrop').forEach(x=>x.remove());$('stage3-notification-panel')?.classList.add('hidden');$('global-search-results')?.classList.add('hidden');return}if(input)return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.shiftKey&&e.key.toLowerCase()==='p'){e.preventDefault();openStage3CommandPanel()}else if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();$('global-search')?.focus();$('global-search-results')?.classList.remove('hidden')}else if(mod&&e.key.toLowerCase()==='r'){e.preventDefault();show(current)}else if(mod&&/^\d$/.test(e.key)){const nav=[...document.querySelectorAll('.nav-item')];nav[Number(e.key)-1]?.click()}})}
initStage3();

/* Stage 15: seven-page information architecture. Existing feature loaders remain reusable. */
const stage15Views={overview:'总览',chat:'对话',config:'配置',library:'跟打',scores:'成绩',ops:'运维',settings:'设置'};
function stage15Tabs(items,active){return `<div class="tabs stage15-tabs">${items.map(x=>`<button class="tab ${x[0]===active?'active':''}" data-stage15-tab="${x[0]}">${x[1]}</button>`).join('')}</div>`}
function stage15Frame(title,subtitle,tabs=''){return `<div class="page-head"><div><h2>${title}</h2><p class="muted">${subtitle}</p></div></div>${tabs}<div id="stage15-page-body"></div>`}
function stage15RestoreTabs(items,active,handler){const root=$('dashboard');if(!root)return;root.querySelectorAll('.stage15-tabs,.tabs:not(.stage15-tabs)').forEach(x=>x.remove());root.insertAdjacentHTML('afterbegin',stage15Tabs(items,active));root.querySelectorAll('[data-stage15-tab]').forEach(b=>b.onclick=()=>handler(b.dataset.stage15Tab))}
function stage15Config(tab='personas'){const tabs=[['personas','人设'],['models','模型'],['groups','群管理']];$('dashboard').innerHTML=stage15Frame('配置','人设、模型与群能力配置',stage15Tabs(tabs,tab));const restore=()=>stage15RestoreTabs(tabs,tab,stage15Config);const done=tab==='personas'?loadPersonasRuntime():tab==='models'?loadModelsRuntime():loadGroupsStage6();Promise.resolve(done).then(restore).catch(restore);setTimeout(restore,1800)}
function stage15Typing(tab='library'){const tabs=[['library','文库'],['contest','赛文']];$('dashboard').innerHTML=stage15Frame('跟打','文库管理与赛文内容',stage15Tabs(tabs,tab));const done=tab==='library'?loadLibraryStage8():loadContestTabStage6('history');Promise.resolve(done).then(()=>stage15RestoreTabs(tabs,tab,stage15Typing))}
function stage15Scores(tab='scores'){const tabs=[['scores','成绩查询'],['rank','排行榜'],['detail','个人成绩详情']];$('dashboard').innerHTML=stage15Frame('成绩','成绩查询、排行榜与个人成绩',stage15Tabs(tabs,tab));if(tab==='detail'){$('stage15-page-body').innerHTML='<div class="card notice">请从成绩查询结果进入个人成绩详情。</div>';stage15RestoreTabs(tabs,tab,stage15Scores);return}const done=tab==='rank'?loadContestTabStage6('rank',{rankType:'image'}):loadContestTabStage6('scores');Promise.resolve(done).then(()=>stage15RestoreTabs(tabs,tab,stage15Scores))}
function stage15Ops(){const shell=`<div class="page-head"><div><h2>运维</h2><p class="muted">服务状态、错误、任务、工具审计与操作审计</p></div></div><div class="stage15-ops-grid"><div id="stage15-services" class="card panel"><h3>服务状态</h3><div class="loading-box">正在加载...</div></div><div id="stage15-errors" class="card panel"><h3>错误日志</h3><div class="loading-box">正在加载...</div></div><div id="stage15-tasks" class="card panel"><h3>任务监控</h3><div class="loading-box">正在加载...</div></div><div id="stage15-tools" class="card panel"><h3>工具调用审计</h3><div class="loading-box">正在加载...</div></div><div id="stage15-media" class="card panel"><h3>媒体缓存</h3><div class="loading-box">正在加载...</div></div><div id="stage15-audit" class="card panel"><h3>操作审计</h3><div class="loading-box">正在加载...</div></div></div>`;$('dashboard').innerHTML=shell;[['stage15-services',runtimeServiceBlock],['stage15-errors',runtimeErrorsBlock],['stage15-tasks',renderRuntimeTasks],['stage15-tools',renderRuntimeAudit],['stage15-media',renderRuntimeMedia],['stage15-audit',async()=>{const r=await api('/api/logs?limit=200');return `<div class="table-wrap"><table><thead><tr><th>时间</th><th>来源</th><th>操作者</th><th>动作</th><th>资源</th></tr></thead><tbody>${(r.items||[]).slice(0,50).map(x=>`<tr><td>${esc(time(x.at||x.created_at))}</td><td>${esc(x.source||'-')}</td><td>${esc(x.actor||x.operator||'-')}</td><td>${esc(x.action||'-')}</td><td>${esc(x.resource||x.item_id||'-')}</td></tr>`).join('')||'<tr><td colspan="5">暂无操作审计</td></tr>'}</tbody></table></div>`}]].forEach(([id,fn])=>loadRuntimeBlock(id,fn));setStatus('运维页面已加载','success')}
function stage15Settings(){current='settings';$('dashboard').innerHTML=stage15Frame('设置','访问管理、配置备份导出与系统信息');tokenManagementPage();current='settings';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view==='settings'));if($('page-title'))$('page-title').textContent='设置';setTimeout(()=>{if(current!=='settings')return;const root=$('dashboard');if(!root)return;root.insertAdjacentHTML('beforeend','<div class="card panel stage15-system-info"><div class="panel-head"><h2>系统信息</h2></div><div class="system-info"><span>服务器时间</span><strong>'+esc(new Date().toLocaleString('zh-CN'))+'</strong><span>后台服务</span><strong>正常运行</strong><span>配置备份</span><strong>可从访问管理区域导出</strong></div></div>');document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view==='settings'))},500)}
