initStage15Nav();

/* Stage 16: keep the current view stable while refreshing dashboard data. */
(function installStage16Refresh(){
  var stage16Run=0, stage16Ready=false, stage16HealthSignature='';
  function stage16Progress(done){
    var bar=document.querySelector('.stage16-progress');
    if(!bar){bar=document.createElement('div');bar.className='stage16-progress';document.body.appendChild(bar)}
    if(done){bar.classList.remove('active');bar.classList.add('done');setTimeout(function(){bar.classList.remove('done')},220)}
    else{bar.classList.remove('done');bar.classList.add('active')}
  }
  function stage16Metric(key,value,change){
    var node=document.querySelector('[data-dashboard-metric="'+key+'"]');
    if(!node)return;
    var valueNode=node.querySelector('.dashboard-metric-value'),trendNode=node.querySelector('.dashboard-trend');
    if(valueNode&&valueNode.textContent!==num(value)){valueNode.textContent=num(value);valueNode.classList.remove('dashboard-metric-value');void valueNode.offsetWidth;valueNode.classList.add('dashboard-metric-value')}
    if(trendNode&&Number.isFinite(Number(change))){var pct=Number(change);trendNode.textContent=(pct>=0?'↑ ':'↓ ')+Math.abs(pct).toFixed(1)+'% 较昨日';trendNode.className='dashboard-trend '+(pct>=0?'up':'down')}
  }
  function stage16Metrics(stats,daily){
    var host=$('dashboard-metrics'),today=Number(daily.today)||0,yesterday=Number(daily.yesterday)||0;
    if(!host)return;
    if(!host.querySelector('[data-dashboard-metric]'))host.innerHTML=stableMetric('▦','群数量',stats.groups,null,'groups')+stableMetric('▥','文库文章',stats.library_texts,null,'library')+stableMetric('◎','成绩记录',stats.score_records,null,'scores')+stableMetric('◉','今日消息量',today,dashboardChange(today,yesterday),'messages');
    stage16Metric('groups',stats.groups,null);stage16Metric('library',stats.library_texts,null);stage16Metric('scores',stats.score_records,null);stage16Metric('messages',today,dashboardChange(today,yesterday));
  }
  function stage16Health(h){
    var score=Math.max(0,Math.min(100,Number(h.score)||0)),signature=JSON.stringify([score,h.issues||[]]);
    if(signature===stage16HealthSignature)return;stage16HealthSignature=signature;
    var card=$('dashboard-health-card')||document.querySelector('.health-score-card'),ring=card?.querySelector('.health-score-ring');
    if(ring){ring.style.setProperty('--score',score*3.6+'deg');ring.classList.toggle('health-good',score>=80);ring.classList.toggle('health-warn',score>=60&&score<80);ring.classList.toggle('health-bad',score<60)}
    if($('health-score-value'))$('health-score-value').textContent=score;
    if($('health-score-summary'))$('health-score-summary').textContent=score>=80?'服务运行良好':score>=60?'服务需要关注':'服务存在风险';
    if($('health-score-issues'))$('health-score-issues').innerHTML=(h.issues||[]).slice(0,3).map(function(x){return '<div>'+esc(readable(x.issue||x.message,'-'))+' <span>'+esc(readable(x.suggestion,'-'))+'</span></div>'}).join('')||'<div class="muted">暂无待处理问题</div>';
  }
  function stage16Events(audit,errors){
    var host=$('dashboard-events')?.querySelector('.dashboard-panel-body');if(!host)return;
    var temp=document.createElement('ul');temp.className='dashboard-timeline';temp.innerHTML=dashboardEvents(Array.isArray(audit)?audit:[],Array.isArray(errors)?errors:[]);
    if(!stage16Ready){host.replaceChildren(temp);stage16Ready=true;return}
    var existing=new Set(Array.from(host.querySelectorAll('li')).map(function(x){return x.textContent.trim()}));
    Array.from(temp.children).reverse().forEach(function(item){if(!existing.has(item.textContent.trim()))host.querySelector('ul')?.insertBefore(item,host.querySelector('ul').firstChild)||host.appendChild(item)});
    var list=host.querySelector('ul');while(list&&list.children.length>20)list.lastElementChild.remove();
  }
  async function stage16LoadDashboard(){
    if(current!=='overview'&&current!=='__dashboard-final__')return;
    var run=++stage16Run,hasLayout=!!$('dashboard-message-chart')&&!!$('stage17-quick');
    clearTimeout(dashboardStableState.timer);stage16Progress(false);
    if(!hasLayout){$('dashboard').innerHTML=finalDashboardShell();console.debug('[dashboard] DOM rebuilt; charts will initialize from current DOM instances');stage16Ready=false;dashboardStableState.messageIds.clear();dashboardStableState.eventSignature='';stage16HealthSignature=''}
    window.__stage17LoadQuick?.();
    current='__dashboard-final__';
    try{
      var results=await Promise.allSettled([api('/api/overview'),api('/api/observability/overview'),api('/api/domain/stats/daily?days=7'),api('/api/domain/recent-messages?limit=15'),api('/api/runtime/audit'),api('/api/health/score'),api('/api/dashboard/advanced')]);
      if(run!==stage16Run||current!=='__dashboard-final__')return;
      var ov=results[0].status==='fulfilled'?results[0].value:{},obs=results[1].status==='fulfilled'?results[1].value:{},daily=results[2].status==='fulfilled'?data(results[2].value):{},snapshot={domain:obs.domain||ov.domain,rpc:obs.rpc||ov.rpc,errors:obs.recent_errors||[]};
      if(results[0].status==='fulfilled')stage16Metrics(data(ov.stats),daily);
      if(results[1].status==='fulfilled')updateStableAlerts(snapshot,snapshot.errors);
      if(results[2].status==='fulfilled'&&await ensureEcharts())updateStableCharts(daily);
      if(results[3].status==='fulfilled')updateStableMessages(data(results[3].value));
      if(results[4].status==='fulfilled')stage16Events(data(results[4].value),snapshot.errors);
      if(results[5].status==='fulfilled')stage16Health(results[5].value);
      if(results[6].status==='fulfilled'){var advanced=results[6].value,domain=advanced.domain?.data||{},auditData=advanced.audit?.data;renderStage2Charts({...domain,audit:Array.isArray(auditData)?auditData:(auditData?.entries||auditData?.items||[])})}
      if(snapshot.domain?.ok===false){$('side-dot').className='dot offline';$('side-status').textContent='离线'}else{$('side-dot').className='dot online';$('side-status').textContent='在线'}
      current='overview';setStatus('仪表盘已更新 · '+new Date().toLocaleTimeString('zh-CN'),'success');
    }catch(error){if(current==='__dashboard-final__')setStatus('仪表盘刷新失败：'+error.message,'error')}
    finally{stage16Progress(true);if(current==='__dashboard-final__')current='overview';if(current==='overview')dashboardStableState.timer=setTimeout(stage16LoadDashboard,10000)}
  }
  loadDashboard=stage16LoadDashboard;
})();

/* Stage 19: consistent list totals and incremental loading indicators. */
(function installListTotals(){
  const listInfo=result=>{const raw=result?.data,payload=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:null,items=Array.isArray(raw)?raw:(Array.isArray(payload?.items)?payload.items:Array.isArray(result?.items)?result.items:[]),total=Number(result?.total??payload?.total??items.length);return {items,total:Number.isFinite(total)?total:items.length}};
  const setMeta=(id,loaded,total)=>{const el=$(id);if(el)el.textContent=`已加载 ${loaded} / 共 ${total} 条`};
  const oldArchive=loadChatArchiveStage8;
  loadChatArchiveStage8=async function(query={}){await oldArchive(query);const more=$('chat-more-archive'),range=$('chat-range-archive');if(!more||!range)return;let total=chatArchiveStage8.items.length;try{const p=new URLSearchParams({limit:'1'}),group=$('chat-archive-group')?.value,q=$('chat-archive-q')?.value;if(group)p.set('group_id',group);if(q)p.set('q',q);const info=listInfo(await api('/api/domain/recent-messages?'+p));total=info.total||total}catch(_){}chatArchiveStage8.total=total;const update=()=>{setMeta('chat-range-archive',chatArchiveStage8.items.length,total);const done=chatArchiveStage8.items.length>=total||chatArchiveStage8.items.length===0;more.hidden=done;more.textContent=done?'已加载全部':`加载更多（${Math.min(200,Math.max(0,total-chatArchiveStage8.items.length))} 条）`};update();more.onclick=async()=>{if(chatArchiveStage8.loading)return;chatArchiveStage8.loading=true;more.disabled=true;more.textContent='加载中...';try{const p=new URLSearchParams({limit:'200',before:String(chatArchiveStage8.before||'')});const group=$('chat-archive-group')?.value,q=$('chat-archive-q')?.value;if(group)p.set('group_id',group);if(q)p.set('q',q);const info=listInfo(await api('/api/domain/recent-messages?'+p));const received=info.items.filter(x=>!chatArchiveStage8.items.some(y=>String(y.message_id)===String(x.message_id)));chatArchiveStage8.items=chatArchiveStage8.items.concat(received);chatArchiveStage8.total=info.total||total;chatArchiveStage8.before=received.length?Number(received[received.length-1].occurred_at):chatArchiveStage8.before;renderChatArchiveStage8();update()}catch(error){more.textContent='加载失败，点击重试';more.disabled=false;more.onclick=()=>more.click()}finally{chatArchiveStage8.loading=false;more.disabled=false}}};
  const oldContest=loadContestTabStage6;
  loadContestTabStage6=async function(tab='history',query={}){await oldContest(tab,query);const panel=document.querySelector('.contest-filter')?.parentElement||document.querySelector('#dashboard .page-head')?.parentElement;if(!panel)return;const rows=tab==='rank'?document.querySelectorAll('.rank-row'):document.querySelectorAll('#dashboard table tbody tr');const meta=document.createElement('span');meta.className='muted stage19-list-total';meta.textContent=`已加载 ${rows.length} / 共 ${contestStage6?.total||contestStage6?.items?.length||rows.length} 条`;const head=panel.querySelector('.page-head')||panel.firstElementChild;if(head&&!panel.querySelector('.stage19-list-total'))head.appendChild(meta)};
  const oldLibrary=loadLibraryStage8;
  loadLibraryStage8=async function(query={}){await oldLibrary(query);const stats=libraryStage8.stats||{},page=Number(libraryStage8.page||1),total=Number(stats.texts||0),pages=Math.max(1,Math.ceil(total/30));const pager=document.querySelector('#library-prev')?.parentElement;if(pager&&!pager.querySelector('.stage19-library-total')){const span=document.createElement('span');span.className='muted stage19-library-total';span.textContent=`共 ${total} 条 / 共 ${pages} 页`;pager.insertBefore(span,pager.firstChild)}};
  const oldOps=stage15Ops;
  stage15Ops=function(){oldOps();setTimeout(()=>{document.querySelectorAll('#stage15-tools,#stage15-audit').forEach(host=>{const table=host.querySelector('table');if(!table||host.querySelector('.stage19-list-total'))return;const count=host.querySelectorAll('tbody tr').length;const meta=document.createElement('div');meta.className='muted stage19-list-total';meta.textContent=`已加载 ${count} / 共 ${count} 条`;host.querySelector('.panel-head')?.appendChild(meta)})},1200)};
})();

/* Stage 18: administrator conversation tools. */
(function installStage18ChatTools(){
  const oldChat=loadChatArchiveStage8;
  function addPanel(){
    if(current!=='chat'||$('stage18-chat-tabs'))return;
    const head=document.querySelector('#dashboard .page-head');if(!head)return;
    head.insertAdjacentHTML('afterend','<div id="stage18-chat-tabs" class="tabs"><button class="tab active" data-chat-mode="archive">聊天记录</button><button class="tab" data-chat-mode="send">发消息</button><button class="tab" data-chat-mode="test">对话测试</button></div><div id="stage18-send-panel" class="card panel stage18-chat-tool hidden"><div class="panel-head"><h2>发消息</h2></div><form id="stage18-send-form"><div class="filter-bar"><select name="target_type"><option value="group">群消息</option><option value="private">私聊消息</option></select><input name="target_id" required placeholder="群号 / QQ号"></div><textarea name="content" required rows="5" placeholder="输入消息内容"></textarea><div class="modal-actions"><button class="button primary" type="submit">发送消息</button></div></form><div id="stage18-send-result" class="muted"></div></div><div id="stage18-test-panel" class="card panel stage18-chat-tool hidden"><div class="panel-head"><h2>对话测试</h2></div><form id="stage18-test-form"><div class="filter-bar"><input name="persona" placeholder="人设（可选）"><input name="model" placeholder="模型（可选）"></div><textarea name="message" required rows="5" placeholder="输入测试消息"></textarea><div class="modal-actions"><button class="button primary" type="submit">测试</button><button class="button secondary" type="button" id="stage18-test-clear">清空</button></div></form><div id="stage18-test-result" class="muted"></div></div>');
    const archiveNodes=()=>[...document.querySelectorAll('#chat-archive-group,#chat-archive-q,#chat-archive-search,#chat-range-archive,#chat-list-archive,#chat-more-archive')].map(x=>x.closest('.filter-bar,.card')||x).filter(Boolean);
    const setMode=mode=>{document.querySelectorAll('[data-chat-mode]').forEach(b=>b.classList.toggle('active',b.dataset.chatMode===mode));const archive=archiveNodes();archive.forEach(x=>x.classList.toggle('hidden',mode!=='archive'));$('stage18-send-panel').classList.toggle('hidden',mode!=='send');$('stage18-test-panel').classList.toggle('hidden',mode!=='test')};document.querySelectorAll('[data-chat-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.chatMode));
    $('stage18-send-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={target_type:f.get('target_type'),target_id:f.get('target_id'),content:f.get('content'),platform:'qq'};if(!confirm('确认向指定 QQ 目标发送这条消息吗？'))return;const out=$('stage18-send-result');out.textContent='正在发送...';try{await api('/api/send-message',{method:'POST',body:JSON.stringify(payload)});out.textContent='发送成功';e.target.reset();toast('消息已发送')}catch(error){out.textContent='发送失败：'+error.message;toast('消息发送失败','error')}};
    $('stage18-test-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),out=$('stage18-test-result');out.textContent='正在测试...';try{const r=await api('/api/persona/test',{method:'POST',body:JSON.stringify({persona:f.get('persona'),message:f.get('message'),model:f.get('model')})});out.innerHTML='<div class="persona-test-answer">'+esc(r.content||r.answer||'-')+'</div><small>耗时：'+esc(r.elapsed_ms||'-')+' ms · token：'+esc(r.usage?.total_tokens??'-')+'</small>'}catch(error){out.textContent='测试失败：'+error.message}};$('stage18-test-clear').onclick=()=>{$('stage18-test-form').reset();$('stage18-test-result').textContent=''};
  }
  loadChatArchiveStage8=async function(){await oldChat();setTimeout(addPanel,80)};
})();

