    if(current==='chat'){
      const items=Array.isArray(chatArchiveStage8?.items)?chatArchiveStage8.items:[];
      return downloadCsv('fm-chat.csv',[['时间','群','发送者','消息'],...items.map(x=>[time(x.occurred_at),x.group_name||x.group_id,x.sender_name||x.sender_id,x.text||''])]);
    }
