      const rows=[...document.querySelectorAll('#dashboard table tbody tr')].filter(x=>!x.hidden).map(r=>[...r.cells].map(c=>c.innerText));
      const head=[...document.querySelectorAll('#dashboard table thead tr:first-child th')].map(x=>x.innerText);
